Make `load()` async and keep it on the main actor. Use `URLSession` for the download and Swift 6.2’s `@concurrent` for synchronous parsing that shouldn’t run on the main actor.

```swift
import Combine
import Foundation

final class FeedModel: ObservableObject {
    @Published private(set) var items: [Item] = []
    @Published private(set) var isLoading = false
    @Published private(set) var loadError: String?

    func load(from url: URL) async {
        guard !isLoading else { return }
        isLoading = true
        loadError = nil
        defer { isLoading = false }

        do {
            let (data, response) = try await URLSession.shared.data(from: url)
            if let http = response as? HTTPURLResponse,
               !(200..<300).contains(http.statusCode) {
                throw URLError(.badServerResponse)
            }

            try Task.checkCancellation()
            let parsed = await Self.parseOffMain(data)
            try Task.checkCancellation()
            items = parsed
        } catch {
            // URLSession cancellation can surface as URLError.cancelled.
            guard !Task.isCancelled else { return }
            loadError = error.localizedDescription
        }
    }

    @concurrent
    private static func parseOffMain(_ data: Data) async -> [Item] {
        Parser.parse(data)
    }
}
```

In SwiftUI, call it with `.task { await model.load(from: feedURL) }` so the load is tied to the view’s lifetime.

Under main-actor-by-default isolation, make `Parser.parse` explicitly `nonisolated` if it’s declared in the app target and would otherwise inherit main-actor isolation. Any helpers it calls must also be safe to use off the main actor. `Item` must be `Sendable` because the parsed array crosses back to the main actor. The cancellation check after parsing prevents a cancelled load from publishing results; it doesn’t interrupt a synchronous parser already in progress.

Use `URLSession` for the download and `@concurrent` for the synchronous parse. With Main Actor default isolation, the model can update its published state directly after each `await`—no dispatch queues needed.

```swift
import Combine
import Foundation

final class FeedModel: ObservableObject {
    @Published private(set) var items: [Item] = []
    @Published private(set) var isLoading = false
    @Published private(set) var error: (any Error)?

    func load(from url: URL) async {
        guard !isLoading else { return }

        isLoading = true
        error = nil
        defer { isLoading = false }

        do {
            let (data, response) = try await URLSession.shared.data(from: url)
            if let http = response as? HTTPURLResponse,
               !(200..<300).contains(http.statusCode) {
                throw URLError(.badServerResponse)
            }

            try Task.checkCancellation()
            let parsed = await FeedParsing.parse(data)
            try Task.checkCancellation()
            items = parsed
        } catch {
            // URLSession may report cancellation as URLError.cancelled.
            if !Task.isCancelled {
                self.error = error
            }
        }
    }
}

nonisolated enum FeedParsing {
    @concurrent
    static func parse(_ data: Data) async -> [Item] {
        Parser.parse(data)
    }
}
```

`Parser.parse` must also be callable off the Main Actor. If `Parser` is stateless and defined in this target, opt its declaration out of default isolation with `nonisolated`. `Item` must be `Sendable` because the parsed array crosses back to the Main Actor; for a value type with sendable fields, use `nonisolated struct Item: Sendable`.

In SwiftUI, call it with `.task { await model.load(from: feedURL) }` to tie cancellation to the view’s lifetime. Cancellation won’t interrupt the synchronous parser midway, but the check after parsing prevents a cancelled task from publishing its results.

Use `URLSession` for the download and a Swift 6.2 `@concurrent` helper for synchronous parsing. Keep the model main-actor isolated. Making `load()` async lets the caller own cancellation—for example, through SwiftUI’s `.task`.

```swift
import Combine
import Foundation

@MainActor
final class FeedModel: ObservableObject {
    @Published private(set) var items: [Item] = []
    @Published private(set) var isLoading = false
    @Published private(set) var loadError: (any Error)?

    private let feedURL: URL

    init(feedURL: URL) {
        self.feedURL = feedURL
    }

    func load() async {
        guard !isLoading else { return }

        isLoading = true
        loadError = nil
        defer { isLoading = false }

        do {
            let (data, response) = try await URLSession.shared.data(from: feedURL)

            if let http = response as? HTTPURLResponse,
               !(200..<300).contains(http.statusCode) {
                throw URLError(.badServerResponse)
            }

            try Task.checkCancellation()
            let parsed = await Self.parseOffMainActor(data)
            try Task.checkCancellation()

            items = parsed
        } catch {
            // URLSession can report cancellation as a URLError.
            guard !Task.isCancelled else { return }
            loadError = error
        }
    }

    @concurrent
    nonisolated private static func parseOffMainActor(_ data: Data) async -> [Item] {
        Parser.parse(data)
    }
}
```

In SwiftUI, call it with `.task { await model.load() }`. A plain `Task {}` created on the main actor inherits that isolation, so wrapping `Parser.parse` in one would not move the parsing off the main actor.

In a main-actor-by-default target, make sure `Parser.parse` is callable from a nonisolated context. If `Parser` is a stateless utility, declaring it `nonisolated enum Parser` is one option. Make `Item` a `Sendable` value type so `[Item]` can cross back to the main actor. The cancellation checks prevent publishing a canceled result; they don’t interrupt a synchronous parser once it starts.

Assuming `feedURL` is an HTTP(S) URL, use `URLSession` for the download and make `load()` async so the caller owns the task’s lifetime. With **Default Actor Isolation = MainActor**, the model needs no explicit `@MainActor` annotation.

```swift
