Use native buttons so both actions work with Tab, Enter, and Space. Give each icon-only button an accessible name, keep the icons decorative, and enlarge the click and tap targets without enlarging the icons.

```tsx
type IconToolbarProps = {
  onDelete: () => void;
  onShare: () => void;
};

export function IconToolbar({ onDelete, onShare }: IconToolbarProps) {
  return (
    <div className="toolbar" role="group" aria-label="Item actions">
      <button
        type="button"
        className="icon-btn"
        onClick={onDelete}
        aria-label="Delete"
      >
        <span className="icon-btn__glyph" aria-hidden="true">
          <TrashIcon />
        </span>
      </button>

      <button
        type="button"
        className="icon-btn"
        onClick={onShare}
        aria-label="Share"
      >
        <span className="icon-btn__glyph" aria-hidden="true">
          <ShareIcon />
        </span>
      </button>
    </div>
  );
}
```

Replace the old `outline: none` rule with a visible focus indicator:

```css
.toolbar {
