  | { status: 'pending'; progress?: number; url?: never; error?: never }
  | { status: 'done'; url: string; progress?: never; error?: never }
  | { status: 'failed'; error: string; progress?: never; url?: never };

function label(upload: Upload): string {
  switch (upload.status) {
    case 'pending':
      return `${upload.progress ?? 0}%`;
    case 'done':
      return upload.url;
    case 'failed':
      return upload.error;
  }
}
```

The `switch` narrows each variant without casts or non-null assertions. The `?: never` fields reject conflicting values even when the object comes from a variable rather than a fresh literal. Enable `exactOptionalPropertyTypes` if you also want to reject explicitly setting those forbidden fields to `undefined`. Validate untrusted input before passing it to `label`.

