  | { kind: "limited"; retryAfterSeconds: number }
  | { kind: "unavailable" };

export interface RateLimiter {
  check(apiKeyId: ApiKeyId): Promise<RateLimitDecision>;
}

export interface RateLimiterOptions {
  redis: RedisClient; // The application's existing Redis client type.
  namespace: string;  // Shared by all instances enforcing this quota.
}

export declare function createRateLimiter(
  options: RateLimiterOptions,
): RateLimiter;
