<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Pine Loop — Arcade Racer</title>
  <style>
    * { box-sizing: border-box; }
    body { margin: 0; overflow: hidden; background: #b8ddf4; color: white;
           font: 16px system-ui, sans-serif; }
    canvas { display: block; }
    #hud, #help { position: fixed; z-index: 1; background: #142334e8;
                  border-radius: 12px; padding: 12px 16px; pointer-events: none; }
    #hud { top: 16px; left: 16px; min-width: 220px; }
    #help { bottom: 16px; left: 16px; right: 16px; width: fit-content; }
    h1 { font-size: 18px; margin: 0 0 8px; }
    .row { display: flex; justify-content: space-between; gap: 20px; }
    output { font-variant-numeric: tabular-nums; }
    #status { color: #bfead3; margin-top: 8px; font-size: 13px; }
  </style>
</head>
<body>
  <section id="hud" aria-label="Race information">
    <h1>Pine Loop</h1>
    <div class="row">Lap <output id="lap">0:00.000</output></div>
    <div class="row">Best <output id="best">—</output></div>
    <div class="row">Completed <output id="count">0</output></div>
    <div id="status">Accelerate to start</div>
  </section>
  <div id="help">WASD / Arrows: drive · R: reset run</div>

  <script type="module">
    import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.166.1/build/three.module.js';

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xb8ddf4);
    scene.fog = new THREE.Fog(0xb8ddf4, 100, 230);

    const camera = new THREE.PerspectiveCamera(60, innerWidth / innerHeight, 0.1, 350);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    renderer.setSize(innerWidth, innerHeight);
    document.body.appendChild(renderer.domElement);

    scene.add(new THREE.HemisphereLight(0xffffff, 0x566846, 2));
    const sun = new THREE.DirectionalLight(0xffeed3, 2);
    sun.position.set(-40, 60, 25);
    scene.add(sun);

    const mat = color => new THREE.MeshStandardMaterial({ color, flatShading: true });
    function box(w, h, d, material, parent, x, y, z) {
      const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
      mesh.position.set(x, y, z);
      parent.add(mesh);
      return mesh;
    }

    box(420, 0.4, 420, mat(0x729c55), scene, 0, -0.22, 0);

    // All road geometry and race checks share this sampled centerline.
    const curve = new THREE.CatmullRomCurve3([
      [0, -49], [43, -44], [65, -16], [56, 22],
      [22, 46], [-18, 44], [-54, 25], [-63, -15], [-38, -42]
    ].map(([x, z]) => new THREE.Vector3(x, 0, z)), true);

    const N = 240, HALF = 5.5;
    const points = [], tangents = [], normals = [];
    for (let i = 0; i < N; i++) {
      const p = curve.getPointAt(i / N);
      const t = curve.getTangentAt(i / N);
      points.push(p);
      tangents.push(t);
      normals.push(new THREE.Vector3(-t.z, 0, t.x));
    }

    function strip(left, right, height, materials, materialForSegment) {
      const vertices = [], indices = [];
      const geometry = new THREE.BufferGeometry();
      for (let i = 0; i < N; i++) {
        for (const offset of [left, right]) {
          const p = points[i].clone().addScaledVector(normals[i], offset);
          vertices.push(p.x, height, p.z);
        }
        const a = 2 * i, b = 2 * ((i + 1) % N);
        indices.push(a, a + 1, b, a + 1, b + 1, b);
        geometry.addGroup(i * 6, 6, materialForSegment(i));
      }
      geometry.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
      geometry.setIndex(indices);
      geometry.computeVertexNormals();
      scene.add(new THREE.Mesh(geometry, materials));
    }

    const asphalt = mat(0x343c48), white = mat(0xf6f0db), red = mat(0xd74739);
    strip(-HALF, HALF, 0, asphalt, () => 0);
    for (const side of [-1, 1]) {
      const edge = side * HALF;
      strip(edge - 0.23, edge + 0.23, 0.025, [white, red],
        i => Math.floor(i / 3) % 2);
    }

    for (let i = 4; i < N - 3; i += 6) {
      const p = points[i], t = tangents[i];
      box(0.13, 0.014, 2, white, scene, p.x, 0.025, p.z)
        .rotation.y = Math.atan2(t.x, t.z);
    }

    const start = points[0], forward = tangents[0];
    const dark = mat(0x151a21);
    for (let row = 0; row < 2; row++) {
      for (let col = 0; col < 12; col++) {
        const width = 2 * HALF / 12;
        const p = start.clone()
          .addScaledVector(normals[0], (col + 0.5) * width - HALF)
          .addScaledVector(forward, (row - 0.5) * 0.65);
        box(width, 0.018, 0.65, (row + col) % 2 ? dark : white,
          scene, p.x, 0.03, p.z).rotation.y = Math.atan2(forward.x, forward.z);
      }
    }

    // Closest point on the sampled road, including its closing segment.
    function locate(x, z) {
      let best = Infinity, progress = 0;
      for (let i = 0; i < N; i++) {
        const a = points[i], b = points[(i + 1) % N];
        const dx = b.x - a.x, dz = b.z - a.z;
        const u = THREE.MathUtils.clamp(
          ((x - a.x) * dx + (z - a.z) * dz) / (dx * dx + dz * dz), 0, 1);
        const d2 = (x - a.x - u * dx) ** 2 + (z - a.z - u * dz) ** 2;
        if (d2 < best) {
          best = d2;
          progress = (i + u) % N;
        }
      }
      return { progress, distance: Math.sqrt(best) };
    }

    let seed = 42;
    function random() {
      seed = (Math.imul(1664525, seed) + 1013904223) >>> 0;
      return seed / 4294967296;
    }

    const bark = mat(0x704a31), pine = [mat(0x245842), mat(0x39714b)];
    const trunkGeo = new THREE.CylinderGeometry(0.16, 0.24, 1.6, 5);
    const crownGeo = new THREE.ConeGeometry(1.5, 3.5, 5);
    for (let i = 0; i < 240; i++) {
      const x = (random() - 0.5) * 190, z = (random() - 0.5) * 160;
      if (locate(x, z).distance < HALF + 5) continue;
      const tree = new THREE.Group();
      const trunk = new THREE.Mesh(trunkGeo, bark);
      trunk.position.y = 0.8;
      const crown = new THREE.Mesh(crownGeo, pine[i % 2]);
      crown.position.y = 2.7;
      tree.add(trunk, crown);
      tree.position.set(x, 0, z);
      tree.scale.setScalar(0.7 + random() * 0.8);
      tree.rotation.y = random() * Math.PI;
      scene.add(tree);
    }

    const car = new THREE.Group();
    scene.add(car);
    box(1.8, 0.52, 3.25, red, car, 0, 0.59, 0);
    box(1.45, 0.48, 1.42, mat(0x24445b), car, 0, 1.05, -0.25);
    box(1.84, 0.12, 0.22, dark, car, 0, 0.43, -1.66);
    for (const x of [-0.63, 0.63]) {
      box(0.38, 0.18, 0.06, white, car, x, 0.63, 1.65);
    }

    const wheelGeo = new THREE.CylinderGeometry(0.36, 0.36, 0.27, 10);
    for (const x of [-0.91, 0.91]) {
      for (const z of [-1.02, 1.02]) {
        const wheel = new THREE.Mesh(wheelGeo, dark);
        wheel.rotation.z = Math.PI / 2;
        wheel.position.set(x, 0.36, z);
        car.add(wheel);
      }
    }

    const lapEl = document.querySelector('#lap');
    const bestEl = document.querySelector('#best');
    const countEl = document.querySelector('#count');
    const statusEl = document.querySelector('#status');
    const storageKey = 'pine-loop-best-v1';
    let bestLap = Infinity;
    try {
      const saved = Number(localStorage.getItem(storageKey));
      if (Number.isFinite(saved) && saved > 0) bestLap = saved;
    } catch { /* Racing still works if storage is unavailable. */ }

    function format(seconds) {
      const ms = Math.floor(seconds * 1000);
      return `${Math.floor(ms / 60000)}:${String(Math.floor(ms / 1000) % 60)
        .padStart(2, '0')}.${String(ms % 1000).padStart(3, '0')}`;
    }

    const keys = new Set();
    const drivingKeys = new Set([
      'KeyW', 'KeyA', 'KeyS', 'KeyD', 'ArrowUp', 'ArrowLeft', 'ArrowDown', 'ArrowRight'
    ]);
    const down = (a, b) => keys.has(a) || keys.has(b);
    addEventListener('keydown', e => {
      if (drivingKeys.has(e.code)) {
        e.preventDefault();
        keys.add(e.code);
      }
      if (e.code === 'KeyR' && !e.repeat) reset();
    });
    addEventListener('keyup', e => keys.delete(e.code));
    addEventListener('blur', () => keys.clear());

    let yaw, speed, last, lapTime, completed, nextGate, running;
    const gates = [N / 4, N / 2, 3 * N / 4, N];
    const chase = new THREE.Vector3(), look = new THREE.Vector3();
    function follow(dt, snap = false) {
      chase.set(car.position.x - Math.sin(yaw) * 9, 5.6,
                car.position.z - Math.cos(yaw) * 9);
      camera.position.lerp(chase, snap ? 1 : 1 - Math.exp(-7 * dt));
      look.set(car.position.x + Math.sin(yaw) * 5, 0.6,
               car.position.z + Math.cos(yaw) * 5);
      camera.lookAt(look);
    }

    function reset() {
      car.position.copy(start).addScaledVector(forward, 0.5);
      yaw = Math.atan2(forward.x, forward.z);
      car.rotation.y = yaw;
      speed = lapTime = completed = nextGate = 0;
      running = false;
      last = locate(car.position.x, car.position.z);
      statusEl.textContent = 'Accelerate to start';
      follow(0, true);
    }

    function finishLap(seconds) {
      completed++;
      if (seconds < bestLap) {
        bestLap = seconds;
        try { localStorage.setItem(storageKey, String(bestLap)); } catch {}
        statusEl.textContent = `New best: ${format(seconds)}`;
      } else {
        statusEl.textContent = `Last lap: ${format(seconds)}`;
      }
    }

    function update(dt) {
      const gas = down('KeyW', 'ArrowUp');
      const brake = down('KeyS', 'ArrowDown');
      const steer = Number(down('KeyA', 'ArrowLeft')) -
                    Number(down('KeyD', 'ArrowRight'));
      const onRoad = last.distance <= HALF;
      if (gas && !brake) speed += (speed < 0 ? 29 : 16) * dt;
      else if (brake && !gas) speed -= (speed > 0 ? 29 : 10) * dt;
      else speed *= Math.exp(-1.35 * dt);

      if (!onRoad) speed *= Math.exp(-3.8 * dt);
      speed = THREE.MathUtils.clamp(speed, -9, 34);
      if (!gas && !brake && Math.abs(speed) < 0.05) speed = 0;

      yaw += steer * Math.sign(speed) * Math.min(Math.abs(speed) / 5, 1)
        * (1.85 - Math.min(Math.abs(speed), 34) * 0.018) * dt;
      car.rotation.y = yaw;
      car.position.x = THREE.MathUtils.clamp(car.position.x + Math.sin(yaw) * speed * dt, -110, 110);
      car.position.z = THREE.MathUtils.clamp(car.position.z + Math.cos(yaw) * speed * dt, -95, 95);

      if (!running && Math.abs(speed) > 0.05) {
        running = true;
        statusEl.textContent = 'Sector 1 / 4';
      }

      const here = locate(car.position.x, car.position.z);
      if (running) {
        lapTime += dt;
        // A shortcut over the grass invalidates the sector sequence.
        if (here.distance > HALF + 2 && nextGate !== 0) {
          nextGate = 0;
          statusEl.textContent = 'Off course — return to sector 1';
        }

        let delta = here.progress - last.progress;
        if (delta < -N / 2) delta += N;
        if (delta > N / 2) delta -= N;
        const gate = gates[nextGate];
        if (delta > 0 && delta < 3 && speed > 0 &&
            last.distance <= HALF && here.distance <= HALF &&
            last.progress < gate && last.progress + delta >= gate) {
          nextGate++;
          if (nextGate === gates.length) {
            const remainder = dt * (last.progress + delta - gate) / delta;
            finishLap(lapTime - remainder);
            lapTime = remainder;
            nextGate = 0;
          } else {
            statusEl.textContent = `Sector ${nextGate + 1} / 4`;
          }
        }
      }
      last = here;
    }

    reset();
    // Fixed physics step keeps handling consistent across refresh rates.
    // Drop long gaps so returning to a hidden tab doesn't move the car.
    const STEP = 1 / 120;
    let previous, accumulator = 0;
    document.addEventListener('visibilitychange', () => {
      previous = undefined;
      accumulator = 0;
      keys.clear();
    });
    renderer.setAnimationLoop(now => {
      const dt = previous === undefined ? 0 : Math.min((now - previous) / 1000, 0.1);
      previous = now;
      accumulator += dt;
      while (accumulator >= STEP) {
        update(STEP);
        accumulator -= STEP;
      }
      follow(dt);
      lapEl.textContent = format(lapTime);
      bestEl.textContent = Number.isFinite(bestLap) ? format(bestLap) : '—';
      countEl.textContent = completed;
      renderer.render(scene, camera);
    });

    addEventListener('resize', () => {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(innerWidth, innerHeight);
    });
  </script>
</body>
</html>
