      mesh.position.set(x, y, z);
      parent.add(mesh);
      return mesh;
    }

    box(scene, mats.grass, 420, 0.2, 420, 0, -0.1, 0);

    // Closed centerline. Arc-length sampling keeps markings and gates evenly spaced.
    const track = new THREE.CatmullRomCurve3([
      [-29, -24], [3, -34], [38, -25], [47, -2], [34, 17],
      [17, 19], [1, 38], [-24, 34], [-46, 13], [-47, -9]
    ].map(([x, z]) => new THREE.Vector3(x, 0, z)), true, 'centripetal');
    track.arcLengthDivisions = 1200;

    const N = 480;
    const halfWidth = 5;
    const samples = Array.from({ length: N }, (_, i) => {
      const p = track.getPointAt(i / N);
      const t = track.getTangentAt(i / N);
      return { p, t, side: new THREE.Vector3(t.z, 0, -t.x) };
    });

    function ribbon(offsetA, offsetB, y, mat, first = 0, count = N) {
      const vertices = [];
      for (let j = first; j <= first + count; j++) {
        const { p, side } = samples[j % N];
        for (const offset of [offsetA, offsetB]) {
          vertices.push(p.x + side.x * offset, y, p.z + side.z * offset);
        }
      }
      const indices = [];
      for (let j = 0; j < count; j++) {
        const a = j * 2;
        indices.push(a, a + 2, a + 1, a + 1, a + 2, a + 3);
      }
      const geometry = new THREE.BufferGeometry();
      geometry.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
      geometry.setIndex(indices);
      geometry.computeVertexNormals();
      scene.add(new THREE.Mesh(geometry, mat));
    }

    ribbon(-halfWidth, halfWidth, 0.025, mats.road);
    for (const side of [-1, 1]) {
      for (let i = 0; i < N; i += 6) {
        const edge = halfWidth * side;
        ribbon(edge - 0.23, edge + 0.23, 0.04,
          i % 12 === 0 ? mats.red : mats.white, i, 6);
      }
    }
    for (let i = 12; i < N - 12; i += 12) {
      ribbon(-0.055, 0.055, 0.041, mats.white, i, 4);
    }

    // Local +Z points down the track; local +X points across it.
    const line = new THREE.Group();
    line.position.copy(samples[0].p);
    line.rotation.y = Math.atan2(samples[0].t.x, samples[0].t.z);
    scene.add(line);
    for (let row = 0; row < 2; row++) {
      for (let col = 0; col < 20; col++) {
        box(line, (row + col) % 2 ? mats.dark : mats.white,
          0.5, 0.015, 0.5, -4.75 + col * 0.5, 0.052, -0.25 + row * 0.5);
      }
    }

    function distanceSqToTrack(x, z) {
      let best = Infinity;
      for (const { p } of samples) {
        const dx = x - p.x;
        const dz = z - p.z;
        best = Math.min(best, dx * dx + dz * dz);
      }
      return best;
    }

    let seed = 24681;
    function random() {
      seed = (Math.imul(1664525, seed) + 1013904223) >>> 0;
      return seed / 4294967296;
    }
    const trunkGeometry = new THREE.CylinderGeometry(0.15, 0.24, 1.6, 5);
    const canopyGeometry = new THREE.ConeGeometry(1.25, 2.5, 6);
    for (let i = 0; i < 145; i++) {
      const x = (random() - 0.5) * 160;
      const z = (random() - 0.5) * 145;
      if (distanceSqToTrack(x, z) < 9 * 9) continue;
      const tree = new THREE.Group();
      tree.position.set(x, 0, z);
      tree.scale.setScalar(0.65 + random() * 0.75);
      tree.rotation.y = random() * Math.PI;
      const trunk = new THREE.Mesh(trunkGeometry, mats.bark);
      trunk.position.y = 0.8;
      tree.add(trunk);
      for (let tier = 0; tier < 2; tier++) {
        const crown = new THREE.Mesh(canopyGeometry, tier ? mats.pineLight : mats.pine);
        crown.position.y = 2 + tier * 1.25;
        crown.scale.setScalar(tier ? 0.76 : 1);
        tree.add(crown);
      }
      scene.add(tree);
    }

    const car = new THREE.Group();
    scene.add(car);
    box(car, mats.red, 1.72, 0.45, 3.25, 0, 0.59, 0);
    box(car, mats.glass, 1.34, 0.44, 1.43, 0, 1.02, -0.29);
    box(car, mats.red, 1.4, 0.09, 1.24, 0, 1.27, -0.32);
    box(car, mats.dark, 1.83, 0.15, 0.24, 0, 0.55, -1.62);

    const tireGeometry = new THREE.CylinderGeometry(0.34, 0.34, 0.27, 10);
    const wheels = [];
    for (const x of [-0.88, 0.88]) {
      for (const z of [-1.02, 1.02]) {
        const pivot = new THREE.Group();
        pivot.position.set(x, 0.35, z);
        car.add(pivot);
        const tire = new THREE.Mesh(tireGeometry, mats.dark);
        tire.rotation.z = Math.PI / 2;
        pivot.add(tire);
        wheels.push({ pivot, front: z > 0 });
      }
      box(car, mats.white, 0.29, 0.15, 0.05, x * 0.7, 0.66, 1.64);
    }

    const ui = Object.fromEntries(
      ['lap', 'best', 'speed', 'status'].map(id => [id, document.getElementById(id)])
    );
    const storageKey = 'pine-loop-best-v1';
    let best = null;
    try {
      const saved = Number(localStorage.getItem(storageKey));
      if (Number.isFinite(saved) && saved > 0) best = saved;
    } catch {
      // The race still works if browser storage is unavailable.
    }

    function formatTime(seconds) {
      if (seconds === null) return '—';
      const ms = Math.floor(seconds * 1000);
      const min = Math.floor(ms / 60000);
      const sec = String(Math.floor(ms / 1000) % 60).padStart(2, '0');
      return `${min}:${sec}.${String(ms % 1000).padStart(3, '0')}`;
    }

    const keys = new Set();
    const drivingKeys = new Set([
      'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight',
      'KeyW', 'KeyA', 'KeyS', 'KeyD', 'Space', 'KeyR'
    ]);
    addEventListener('keydown', event => {
      if (!drivingKeys.has(event.code)) return;
      event.preventDefault();
      keys.add(event.code);
      if (event.code === 'KeyR' && !event.repeat) reset();
    });
    addEventListener('keyup', event => keys.delete(event.code));
    addEventListener('blur', () => keys.clear());
    const held = (...codes) => codes.some(code => keys.has(code));

    const gates = [0, N / 4, N / 2, 3 * N / 4].map(i => samples[i]);
    let speed = 0;
    let yaw = 0;
    let simTime = 0;
    let lapStart = null;
    let nextGate = 0;
    const previous = new THREE.Vector3();
    const cameraGoal = new THREE.Vector3();
    const lookGoal = new THREE.Vector3();

    function updateCamera(dt, snap = false) {
      const fx = Math.sin(yaw);
      const fz = Math.cos(yaw);
      cameraGoal.set(car.position.x - fx * 8.5, 5.5, car.position.z - fz * 8.5);
      camera.position.lerp(cameraGoal, snap ? 1 : 1 - Math.exp(-7 * dt));
      lookGoal.set(car.position.x + fx * 3.5, 0.9, car.position.z + fz * 3.5);
      camera.lookAt(lookGoal);
    }

    function reset() {
      const spawn = samples[N - 12];
      car.position.copy(spawn.p);
      yaw = Math.atan2(spawn.t.x, spawn.t.z);
      car.rotation.y = yaw;
      speed = 0;
      lapStart = null;
      nextGate = 0;
      ui.status.textContent = 'Cross the line to start';
      updateCamera(0, true);
    }

    // Return the fraction of this physics step at which the car crossed
    // the finite gate, or null if it missed or crossed in reverse.
    function forwardCrossing(gate, from, to) {
      const ax = from.x - gate.p.x;
      const az = from.z - gate.p.z;
      const bx = to.x - gate.p.x;
      const bz = to.z - gate.p.z;
      const a = ax * gate.t.x + az * gate.t.z;
      const b = bx * gate.t.x + bz * gate.t.z;
      if (a >= 0 || b < 0) return null;
      const u = -a / (b - a);
      const x = ax + (bx - ax) * u;
      const z = az + (bz - az) * u;
      return Math.abs(x * gate.side.x + z * gate.side.z) <= halfWidth ? u : null;
    }

    function checkLap(dt) {
      const u = forwardCrossing(gates[nextGate], previous, car.position);
      if (u === null) return;
      if (nextGate !== 0) {
        nextGate = (nextGate + 1) % gates.length;
        ui.status.textContent = nextGate === 0 ? 'Finish line ahead' : 'Lap in progress';
        return;
      }

      const crossingTime = simTime + u * dt;
      if (lapStart === null) {
        ui.status.textContent = 'Lap in progress';
      } else {
        const lap = crossingTime - lapStart;
        if (best === null || lap < best) {
          best = lap;
          try { localStorage.setItem(storageKey, String(best)); } catch {}
          ui.status.textContent = `New best! ${formatTime(lap)}`;
        } else {
          ui.status.textContent = `Last lap: ${formatTime(lap)}`;
        }
      }
      lapStart = crossingTime;
      nextGate = 1;
    }

    function approach(value, target, amount) {
      return value < target ? Math.min(target, value + amount)
                            : Math.max(target, value - amount);
    }

    function step(dt) {
      previous.copy(car.position);
      const offRoad = distanceSqToTrack(previous.x, previous.z) > halfWidth ** 2;
      const gas = held('KeyW', 'ArrowUp');
      const brake = held('KeyS', 'ArrowDown');
      const handbrake = held('Space');
      const steer = Number(held('KeyA', 'ArrowLeft')) -
                    Number(held('KeyD', 'ArrowRight'));

      if (gas && !brake) {
        speed = approach(speed, offRoad ? 9 : 34, (speed < 0 ? 29 : 18) * dt);
      } else if (brake && !gas) {
        speed = approach(speed, offRoad ? -6 : -10, (speed > 0 ? 32 : 10) * dt);
      } else {
        speed = approach(speed, 0, (offRoad ? 10 : 4) * dt);
      }
      if (handbrake) speed = approach(speed, 0, 24 * dt);

      const steeringGrip = Math.min(Math.abs(speed) / 4, 1);
      const turnRate = handbrake ? 2.7 : 2.25 - 0.024 * Math.abs(speed);
      yaw += steer * Math.sign(speed) * steeringGrip * turnRate * dt;
      car.rotation.y = yaw;
      car.position.x += Math.sin(yaw) * speed * dt;
      car.position.z += Math.cos(yaw) * speed * dt;
      for (const wheel of wheels) {
        if (wheel.front) wheel.pivot.rotation.y = steer * 0.26;
      }

      // The scenery is decorative; reset if the car leaves the play area.
      if (Math.abs(car.position.x) > 105 || Math.abs(car.position.z) > 105) {
        reset();
      } else {
        checkLap(dt);
      }
      simTime += dt;
    }

    reset();
    const fixedStep = 1 / 120;
    let accumulator = 0;
    let lastFrame = null;

    document.addEventListener('visibilitychange', () => {
      // Don't advance the race clock or keep a key held while the tab is hidden.
      keys.clear();
      lastFrame = null;
      accumulator = 0;
    });

    function animate(now) {
      requestAnimationFrame(animate);
      const dt = lastFrame === null ? 0 : Math.min((now - lastFrame) / 1000, 0.1);
      lastFrame = now;
      accumulator += dt;
      while (accumulator >= fixedStep) {
        step(fixedStep);
        accumulator -= fixedStep;
      }
      updateCamera(dt);
      ui.lap.textContent = formatTime(lapStart === null ? null : simTime - lapStart);
      ui.best.textContent = formatTime(best);
      ui.speed.textContent = `${Math.round(Math.abs(speed) * 3.6)} km/h`;
      renderer.render(scene, camera);
    }
    requestAnimationFrame(animate);

    addEventListener('resize', () => {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(innerWidth, innerHeight);
    });
  </script>
</body>
</html>
```

### Run and verify

From the folder containing `index.html`, run `python -m http.server 8000`, then open `http://localhost:8000`. I haven’t run it here; this is the browser smoke test I’d use:

1. **Rendering and controls:** Confirm the circuit, car, and HUD appear without console errors. Check both keyboard layouts, braking into reverse, and the handbrake. Drive onto the grass and confirm the car slows down.
2. **Lap counting:** Confirm the timer is blank at spawn and starts on the first forward crossing. Reverse back over the line and drive forward again without completing the circuit; the crossing should not record a lap. Then drive the full circuit: the finish should record a best and immediately start the next lap.
3. **Best time and reset:** Finish a slower lap and confirm the best stays unchanged. Press R and verify the car returns to the start with a blank lap timer but the same best. Reload at the same URL and confirm the best is restored.
4. **Browser behavior:** Resize the window and check that the view doesn’t stretch. Switch tabs mid-lap and return; the timer should not include time spent in the hidden tab, and no controls should be stuck.

Save this as `index.html`. It’s a single-file Three.js game with a closed oval track, a chase camera, and a best lap saved in your browser. Use **WASD or the arrow keys** to drive, **Space** to brake, and **R** to restart the current lap.

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Mini Apex — Arcade Racer</title>
  <style>
    * { box-sizing: border-box; }
    body {
      margin: 0;
      overflow: hidden;
      background: #a7d8f4;
      color: white;
      font: 15px/1.4 system-ui, sans-serif;
    }
    canvas { display: block; }
    #hud {
      position: fixed;
      top: 16px;
      left: 16px;
      padding: 14px 18px;
      border-radius: 12px;
      background: #101b2ce8;
      pointer-events: none;
      font-variant-numeric: tabular-nums;
    }
    h1 { margin: 0 0 8px; font-size: 20px; }
    #hint { margin-top: 8px; color: #bcd1e7; font-size: 12px; }
    #status { color: #ffe186; }
  </style>
</head>
<body>
  <aside id="hud">
    <h1>Mini Apex</h1>
    <div>Lap <b id="lap">1</b> · <b id="time">0:00.000</b></div>
    <div>Best: <b id="best">—</b></div>
    <div id="status">Drive forward to start</div>
    <div id="hint">WASD / arrows · Space: brake · R: restart</div>
  </aside>

  <script type="module">
    import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xa7d8f4);
    scene.fog = new THREE.Fog(0xa7d8f4, 90, 210);

    const camera = new THREE.PerspectiveCamera(60, innerWidth / innerHeight, 0.1, 240);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    renderer.setSize(innerWidth, innerHeight);
    document.body.appendChild(renderer.domElement);

    scene.add(new THREE.HemisphereLight(0xffffff, 0x596044, 2.1));
    const sun = new THREE.DirectionalLight(0xffedd0, 2.2);
    sun.position.set(-24, 40, 15);
    scene.add(sun);

    const material = color => new THREE.MeshStandardMaterial({ color, flatShading: true });
    const grass = material(0x659448);
    const asphalt = material(0x3b4149);
    const white = material(0xf6f4e8);
    const red = material(0xeb5045);
    const black = material(0x171b21);
    const glass = material(0x85cfe9);
    const trunk = material(0x77533d);
    const leaves = material(0x2e7045);

    function box(parent, mat, w, h, d, x, y, z) {
      const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
      mesh.position.set(x, y, z);
      parent.add(mesh);
      return mesh;
    }
    box(scene, grass, 400, 0.2, 400, 0, -0.12, 0);

    // Elliptical track. The same parameterization drives the road and lap gates.
    const A = 42, B = 27;
    const INNER = 0.83, OUTER = 1.17;
    const TAU = 2 * Math.PI;
    const point = (angle, scale = 1) =>
      new THREE.Vector3(A * scale * Math.cos(angle), 0, B * scale * Math.sin(angle));

    function strip(inner, outer, start, end, steps, y, mat) {
      const vertices = [];
      const indices = [];
      for (let i = 0; i <= steps; i++) {
        const angle = start + (end - start) * i / steps;
        for (const scale of [inner, outer]) {
          const p = point(angle, scale);
          vertices.push(p.x, y, p.z);
        }
        if (i < steps) {
          const j = 2 * i;
          indices.push(j, j + 2, j + 1, j + 1, j + 2, j + 3);
        }
      }
      const geometry = new THREE.BufferGeometry();
      geometry.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
      geometry.setIndex(indices);
      geometry.computeVertexNormals();
      scene.add(new THREE.Mesh(geometry, mat));
    }

    strip(INNER, OUTER, 0, TAU, 128, 0.01, asphalt);
    for (let i = 0; i < 80; i++) {
      const start = TAU * i / 80;
      const end = TAU * (i + 1) / 80;
      const color = i % 2 ? white : red;
      strip(INNER, INNER + 0.018, start, end, 2, 0.025, color);
      strip(OUTER - 0.018, OUTER, start, end, 2, 0.025, color);
      if (i > 1 && i < 78 && i % 2 === 0) {
        strip(0.997, 1.003, start, end, 2, 0.025, white);
      }
    }

    // The finish line is at angle zero, across the road on the positive X side.
    const tileWidth = A * (OUTER - INNER) / 14;
    for (let row = 0; row < 2; row++) {
      for (let col = 0; col < 14; col++) {
        box(scene, (row + col) % 2 ? black : white, tileWidth, 0.02, 0.42,
          A * INNER + (col + 0.5) * tileWidth, 0.025, (row - 0.5) * 0.42);
      }
    }

    const treeTop = new THREE.ConeGeometry(1.25, 3.5, 5);
    for (let i = 0; i < 42; i++) {
      const angle = i * 2.399963;
      const scale = i % 3 === 0 ? 0.34 + (i % 7) * 0.045 : 1.32 + (i % 8) * 0.055;
      const p = point(angle, scale);
      box(scene, trunk, 0.33, 1.4, 0.33, p.x, 0.7, p.z);
      const crown = new THREE.Mesh(treeTop, leaves);
      crown.position.set(p.x, 2.25, p.z);
      crown.rotation.y = angle;
      scene.add(crown);
    }

    // The car's local forward axis is +Z.
    const car = new THREE.Group();
    scene.add(car);
    box(car, red, 1.65, 0.48, 3.0, 0, 0.57, 0);
    box(car, glass, 1.22, 0.48, 1.35, 0, 1.02, -0.26);
    box(car, white, 0.25, 0.025, 1.0, 0, 0.82, 0.91);
    for (const x of [-0.86, 0.86]) {
      for (const z of [-0.94, 0.94]) {
        const wheel = new THREE.Mesh(new THREE.CylinderGeometry(0.34, 0.34, 0.30, 10), black);
        wheel.rotation.z = Math.PI / 2;
        wheel.position.set(x, 0.35, z);
        car.add(wheel);
      }
    }

    const $ = id => document.getElementById(id);
    const storageKey = 'mini-apex-best-v1';
    let best = Infinity;
    try {
      const saved = Number(localStorage.getItem(storageKey));
      if (Number.isFinite(saved) && saved > 0) best = saved;
    } catch {
      // Racing still works if browser storage is unavailable.
    }

    function format(seconds) {
      const ms = Math.floor(seconds * 1000);
      return `${Math.floor(ms / 60000)}:${String(Math.floor(ms / 1000) % 60)
        .padStart(2, '0')}.${String(ms % 1000).padStart(3, '0')}`;
    }
    function showBest() {
      $('best').textContent = Number.isFinite(best) ? format(best) : '—';
    }
    showBest();

    const keys = new Set();
    const controls = new Set([
      'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight',
      'KeyW', 'KeyA', 'KeyS', 'KeyD', 'Space', 'KeyR'
    ]);
    addEventListener('keydown', event => {
      if (!controls.has(event.code)) return;
      event.preventDefault();
      keys.add(event.code);
      if (event.code === 'KeyR' && !event.repeat) reset();
    });
    addEventListener('keyup', event => keys.delete(event.code));
    addEventListener('blur', () => keys.clear());

    const pressed = (...codes) => codes.some(code => keys.has(code));
    const forward = new THREE.Vector3();
    const desiredCamera = new THREE.Vector3();
    const target = new THREE.Vector3();
    let yaw, speed, lapStart, lap = 1, nextGate, invalid, previousAngle;

    function placeCamera(blend) {
      forward.set(Math.sin(yaw), 0, Math.cos(yaw));
      desiredCamera.copy(car.position).addScaledVector(forward, -8.5);
      desiredCamera.y += 5.2;
      camera.position.lerp(desiredCamera, blend);
      target.copy(car.position).addScaledVector(forward, 4);
      target.y += 0.65;
      camera.lookAt(target);
    }

    function reset() {
      const angle = -0.115;
      car.position.copy(point(angle));
      yaw = Math.atan2(-A * Math.sin(angle), B * Math.cos(angle));
      car.rotation.y = yaw;
      speed = 0;
      lapStart = null;
      nextGate = 0;
      invalid = false;
      previousAngle = angle;
      $('lap').textContent = lap;
      $('time').textContent = format(0);
      $('status').textContent = 'Cross the line to start';
      placeCamera(1);
    }
    reset();

    // A valid lap crosses three quarter-track gates in order, then the
    // finish line. Gate crossings must be forward and on the road.
    const gates = [Math.PI / 2, Math.PI, 3 * Math.PI / 2];
    const wrap = angle => Math.atan2(Math.sin(angle), Math.cos(angle));

    function updateLap(now, angle, onRoad) {
      const change = wrap(angle - previousAngle);
      const crossed = gate => {
        const distance = (gate - previousAngle + TAU) % TAU;
        return change > 0 && distance > 0 && distance <= change;
      };

      if (lapStart !== null && !onRoad) invalid = true;
      if (onRoad && speed > 0) {
        if (lapStart !== null && nextGate < gates.length && crossed(gates[nextGate])) {
          nextGate++;
        }
        if (crossed(0)) {
          if (lapStart !== null && !invalid && nextGate === gates.length) {
            const elapsed = (now - lapStart) / 1000;
            if (elapsed < best) {
              best = elapsed;
              try { localStorage.setItem(storageKey, String(best)); } catch {}
              showBest();
            }
            $('lap').textContent = ++lap;
          }
          lapStart = now;
          nextGate = 0;
          invalid = false;
        }
      }
      previousAngle = angle;

      if (lapStart !== null) {
        $('time').textContent = format((now - lapStart) / 1000);
        $('status').textContent = invalid
          ? 'Lap invalid: off track'
          : `Checkpoints: ${nextGate} / ${gates.length}`;
      }
    }

    let last = performance.now();
    function frame(now) {
      // Clamp physics after a pause; the lap clock still measures real time.
      const dt = Math.max(0, Math.min((now - last) / 1000, 0.05));
      last = now;
      const gas = Number(pressed('KeyW', 'ArrowUp')) -
        Number(pressed('KeyS', 'ArrowDown'));
      const steer = Number(pressed('KeyA', 'ArrowLeft')) -
        Number(pressed('KeyD', 'ArrowRight'));
      const radius = () => Math.hypot(car.position.x / A, car.position.z / B);
      const onTrack = r => r >= INNER && r <= OUTER;
      const road = onTrack(radius());

      speed += gas * 15 * dt;
      const drag = pressed('Space') ? 7 : road ? (gas ? 0.45 : 1.5) : 3.8;
      speed *= Math.exp(-drag * dt);
      speed = THREE.MathUtils.clamp(speed, -8, road ? 25 : 9);
      yaw += steer * Math.sign(speed) * 1.85 *
        THREE.MathUtils.clamp(Math.abs(speed) / 6, 0, 1) * dt;
      car.rotation.y = yaw;
      car.position.x += Math.sin(yaw) * speed * dt;
      car.position.z += Math.cos(yaw) * speed * dt;
      car.position.x = THREE.MathUtils.clamp(car.position.x, -85, 85);
      car.position.z = THREE.MathUtils.clamp(car.position.z, -85, 85);

      const angle = Math.atan2(car.position.z / B, car.position.x / A);
      updateLap(now, angle, onTrack(radius()));
      placeCamera(1 - Math.exp(-8 * dt));
      renderer.render(scene, camera);
      requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);

    addEventListener('resize', () => {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(innerWidth, innerHeight);
    });
  </script>
</body>
</html>
```

