  <script type="module">
    import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xa8d9ed);
    scene.fog = new THREE.Fog(0xa8d9ed, 85, 200);
    const camera = new THREE.PerspectiveCamera(58, 1, 0.1, 250);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    document.body.append(renderer.domElement);

    function resize() {
      renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
      renderer.setSize(innerWidth, innerHeight);
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
    }
    addEventListener('resize', resize);
    resize();

    scene.add(new THREE.HemisphereLight(0xfff6dd, 0x57775d, 2));
    const sun = new THREE.DirectionalLight(0xffe1ae, 2);
    sun.position.set(-35, 55, -20);
    scene.add(sun);

    const material = color => new THREE.MeshStandardMaterial({ color, flatShading: true });
    function mesh(geometry, mat, parent = scene, x = 0, y = 0, z = 0) {
      const object = new THREE.Mesh(geometry, mat);
      object.position.set(x, y, z);
      parent.add(object);
      return object;
    }

    const ground = mesh(new THREE.PlaneGeometry(500, 500), material(0x63954e));
    ground.rotation.x = -Math.PI / 2;

    const curve = new THREE.CatmullRomCurve3(
      [[0, -42], [37, -38], [57, -12], [44, 23], [12, 41],
       [-27, 31], [-53, 7], [-43, -28]]
        .map(([x, z]) => new THREE.Vector3(x, 0, z)),
      true
    );
    curve.arcLengthDivisions = 1200;
    const length = curve.getLength();
    const halfRoad = 5;
    const segments = 240;

    function frame(u) {
      u = ((u % 1) + 1) % 1;
      const center = curve.getPointAt(u);
      const forward = curve.getTangentAt(u);
      const right = new THREE.Vector3(-forward.z, 0, forward.x);
      return { center, forward, right };
    }

    function strip(from, to, y, color, visible = () => true) {
      const vertices = [];
      function point(f, offset) {
        const p = f.center.clone().addScaledVector(f.right, offset);
        return [p.x, y, p.z];
      }
      for (let i = 0; i < segments; i++) {
        if (!visible(i)) continue;
        const a = frame(i / segments), b = frame((i + 1) / segments);
        const al = point(a, from), ar = point(a, to);
        const bl = point(b, from), br = point(b, to);
        vertices.push(...al, ...bl, ...ar, ...ar, ...bl, ...br);
      }
      const geometry = new THREE.BufferGeometry();
      geometry.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
      geometry.computeVertexNormals();
      const mat = material(color);
      mat.side = THREE.DoubleSide;
      mesh(geometry, mat);
    }

    strip(-halfRoad, halfRoad, .03, 0x343b47);
    for (const side of [-1, 1]) {
      const [a, b] = [side * 4.68, side * 5.25].sort((x, y) => x - y);
      strip(a, b, .042, 0xfff4d8, i => i % 6 < 3);
      strip(a, b, .042, 0xef584a, i => i % 6 >= 3);
    }
    strip(-.07, .07, .045, 0xc2bfaa, i => i % 8 < 3 && i > 1);

    for (let i = 0; i < 10; i++) {
      strip(i - 5, i - 4, .055, i % 2 ? 0x141922 : 0xffffff, j => j === 0);
      strip(i - 5, i - 4, .055, i % 2 ? 0xffffff : 0x141922, j => j === segments - 1);
    }

    const bark = material(0x6a432e), needles = material(0x244f3a);
    const trunk = new THREE.CylinderGeometry(.21, .31, 1.7, 5);
    const crown = new THREE.ConeGeometry(1.35, 3.4, 5);
    for (let i = 0; i < 64; i++) {
      const { center, right } = frame(i / 64);
      const side = i % 3 ? -1 : 1;
      center.addScaledVector(right, side * (10 + 4 * Math.sin(i * 17) ** 2));
      mesh(trunk, bark, scene, center.x, .85, center.z);
      const tree = mesh(crown, needles, scene, center.x, 2.7, center.z);
      tree.rotation.y = i;
      tree.scale.y = .8 + .45 * Math.sin(i * 11) ** 2;
    }

    const car = new THREE.Group();
    scene.add(car);
    const paint = material(0xffad29), glass = material(0x17445b);
    const rubber = material(0x182026), tail = material(0xe92f31);
    mesh(new THREE.BoxGeometry(1.65, .46, 2.8), paint, car, 0, .54, 0);
    mesh(new THREE.BoxGeometry(1.32, .45, 1.36), glass, car, 0, .98, .15);
    mesh(new THREE.BoxGeometry(1.36, .12, 1.39), paint, car, 0, 1.24, .15);
    const tire = new THREE.CylinderGeometry(.31, .31, .28, 8);
    for (const x of [-.82, .82]) {
      for (const z of [-.91, .91]) {
        mesh(tire, rubber, car, x, .33, z).rotation.z = Math.PI / 2;
      }
      mesh(new THREE.BoxGeometry(.38, .15, .06), tail, car, x * .72, .59, 1.42);
    }

    const keys = new Set();
    const controls = new Set([
      'KeyW', 'KeyA', 'KeyS', 'KeyD', 'ArrowUp', 'ArrowDown',
      'ArrowLeft', 'ArrowRight', 'KeyR'
    ]);
    const held = (a, b) => keys.has(a) || keys.has(b);
    const storageKey = 'pine-loop-best-v1';
    let best = null;
    try {
      const saved = Number(localStorage.getItem(storageKey));
      if (Number.isFinite(saved) && saved > 0) best = saved;
    } catch {}

    const race = { distance: 0, offset: 0, speed: 0, lap: 1, time: 0, last: null };
    const hud = Object.fromEntries(
      ['lap', 'time', 'last', 'best', 'status'].map(id => [id, document.getElementById(id)])
    );
    function format(seconds) {
      if (seconds === null) return '--';
      const ms = Math.floor(seconds * 1000);
      return `${Math.floor(ms / 60000)}:${String(Math.floor(ms / 1000) % 60).padStart(2, '0')}.${String(ms % 1000).padStart(3, '0')}`;
    }

    addEventListener('keydown', event => {
      if (!controls.has(event.code)) return;
      event.preventDefault();
      keys.add(event.code);
      if (event.code === 'KeyR' && !event.repeat) {
        Object.assign(race, { distance: 0, offset: 0, speed: 0, lap: 1, time: 0, last: null });
        view(0, true);
      }
    });
    addEventListener('keyup', event => keys.delete(event.code));
    addEventListener('blur', () => keys.clear());
    document.addEventListener('visibilitychange', () => {
      keys.clear();
      previous = null;
    });

    function drive(dt) {
      const throttle = held('KeyW', 'ArrowUp');
      const brake = held('KeyS', 'ArrowDown');
      const steer = Number(held('KeyD', 'ArrowRight')) - Number(held('KeyA', 'ArrowLeft'));
      const grass = Math.abs(race.offset) > halfRoad;
      const limit = grass ? 11 : 36;
      const acceleration = brake ? -38 : throttle ? 19 : -8;
      race.speed = Math.max(0, race.speed + acceleration * dt);
      if (race.speed > limit) race.speed = Math.max(limit, race.speed - 72 * dt);
      race.offset = THREE.MathUtils.clamp(
        race.offset + steer * Math.min(race.speed * .52, 12) * dt, -8, 8
      );

      const travel = race.speed * dt;
      const remaining = length - race.distance;
      if (travel >= remaining) {
        const beforeLine = dt * remaining / travel;
        race.last = race.time + beforeLine;
        if (best === null || race.last < best) {
          best = race.last;
          try { localStorage.setItem(storageKey, String(best)); } catch {}
        }
        race.lap++;
        race.distance = travel - remaining;
        race.time = dt - beforeLine;
      } else {
        if (race.distance > 0 || travel > 0 || race.lap > 1) race.time += dt;
        race.distance += travel;
      }
    }

    const eye = new THREE.Vector3();
    const target = new THREE.Vector3();
    function view(dt, snap = false) {
      const { center, forward, right } = frame(race.distance / length);
      car.position.copy(center).addScaledVector(right, race.offset);
      car.position.y = .045;
      car.rotation.y = Math.atan2(-forward.x, -forward.z);
      eye.copy(car.position).addScaledVector(forward, -9);
      eye.y += 5;
      camera.position.lerp(eye, snap ? 1 : 1 - Math.exp(-9 * dt));
      target.copy(car.position).addScaledVector(forward, 6);
      target.y += 1;
      camera.lookAt(target);
    }

    let previous = null;
    view(0, true);
    renderer.setAnimationLoop(now => {
      const elapsed = previous === null ? 0 : (now - previous) / 1000;
      previous = now;
      if (document.hidden) return;
      const dt = Math.min(elapsed, .1);
      const steps = Math.max(1, Math.ceil(dt * 120));
      for (let i = 0; i < steps; i++) drive(dt / steps);
      view(dt);
      hud.lap.textContent = race.lap;
      hud.time.textContent = format(race.time);
      hud.last.textContent = format(race.last);
      hud.best.textContent = format(best);
      hud.status.textContent = Math.abs(race.offset) > halfRoad ? 'Grass' : 'Road';
      renderer.render(scene, camera);
    });
  </script>
