    const rockGeo = new T.DodecahedronGeometry(1);
    const rocks = [material(0xb36d43), material(0x99583d), material(0xe6b780)];
    const cactus = material(0x416d51);
    for (let i = 0; i < 90; i++) {
      const angle = random() * turn;
      const offset = i < 38 ? -9 - random() * 12 : 10 + random() * 45;
      const p = point(angle, offset);
      if (i % 5 === 0) {
        const h = 1.7 + random() * 2;
        box(scene, cactus, p.x, h / 2, p.z, .48, h, .48);
        box(scene, cactus, p.x + .39, h * .55, p.z, .65, .28, .28);
        box(scene, cactus, p.x + .65, h * .69, p.z, .28, h * .32, .28);
      } else {
        const rock = mesh(rockGeo, rocks[i % rocks.length]);
        const size = .65 + random() * 2.4;
        rock.position.set(p.x, size * .31, p.z);
        rock.scale.set(size, size * (.5 + random()), size * .85);
        rock.rotation.y = random() * turn;
      }
    }

    const car = new T.Group();
    scene.add(car);
    const paint = material(0x3ae3c5);
    box(car, paint, 0, .63, 0, 1.95, .52, 3.35);
    box(car, dark, 0, 1.04, -.18, 1.42, .45, 1.55);
    box(car, paint, 0, 1.29, -.22, 1.36, .12, 1.13);
    const tail = material(0xf25541);
    for (const x of [-.87, .87]) {
      for (const z of [-1.02, 1.02]) {
        box(car, dark, x, .39, z, .43, .7, .72);
      }
      box(car, chalk, x * .77, .68, 1.69, .36, .16, .08);
      box(car, tail, x * .77, .68, -1.69, .36, .16, .08);
    }

    const keys = new Set();
    const drivingKeys = new Set([
      "KeyW", "KeyA", "KeyS", "KeyD",
      "ArrowUp", "ArrowLeft", "ArrowDown", "ArrowRight", "KeyR"
    ]);
    const held = (a, b) => keys.has(a) || keys.has(b);
    const ready = "Press W or ↑ to start the clock.";
    const restart = el("restart");

    function reset() {
      run = freshRun();
      keys.clear();
      status.textContent = ready;
    }

    addEventListener("keydown", event => {
      if (event.ctrlKey || event.metaKey || event.altKey) return;
      if (!drivingKeys.has(event.code)) return;
      event.preventDefault();
      if (event.code === "KeyR") {
        if (!event.repeat) reset();
      } else {
        keys.add(event.code);
      }
    });
    addEventListener("keyup", event => keys.delete(event.code));
    addEventListener("blur", () => keys.clear());
    document.addEventListener("visibilitychange", () => keys.clear());
    restart.addEventListener("click", reset);
    restart.disabled = false;
    status.textContent = ready;

    function format(ms) {
      const whole = Math.max(0, Math.floor(ms));
      const minutes = Math.floor(whole / 60000);
      const seconds = String(Math.floor(whole / 1000) % 60).padStart(2, "0");
      return `${minutes}:${seconds}.${String(whole % 1000).padStart(3, "0")}`;
    }

    function update(now, dt) {
      const throttle = held("KeyW", "ArrowUp");
      const brake = held("KeyS", "ArrowDown");
      const steer = Number(held("KeyD", "ArrowRight"))
        - Number(held("KeyA", "ArrowLeft"));

      if (run.lapStart === null && throttle && !brake) {
        run.lapStart = now;
        status.textContent = "Lap 1 in progress.";
      }

      const pushingRail = steer * run.offset > 0 && Math.abs(run.offset) > 4.04;
      const limit = pushingRail ? 15 : 34;
      const accel = brake ? -34 : throttle ? 15 : -6;
      run.speed = clamp(run.speed + accel * dt, 0, 34);
      if (run.speed > limit) run.speed = Math.max(limit, run.speed - 26 * dt);

      run.offset = clamp(run.offset + steer * run.speed * .37 * dt, -4.05, 4.05);
      const previous = run.angle;
      const tangent = point(previous + .001, run.offset)
        .sub(point(previous - .001, run.offset));
      run.angle += run.speed * dt / (tangent.length() / .002);

      const finish = (run.laps + 1) * turn;
      if (run.angle >= finish && run.lapStart !== null) {
        const fraction = (finish - previous) / (run.angle - previous);
        const crossedAt = now - (1 - fraction) * dt * 1000;
        const lap = crossedAt - run.lapStart;
        run.lapStart = crossedAt;
        run.laps++;
        if (best === null || lap < best) {
          best = lap;
          try { localStorage.setItem(storageKey, String(best)); } catch {}
          status.textContent = `Lap ${run.laps} · New best ${format(lap)}`;
        } else {
          status.textContent = `Lap ${run.laps} · ${format(lap)}`;
        }
      }

      car.position.copy(point(run.angle, run.offset));
      const forward = point(run.angle + .005, run.offset).sub(car.position).normalize();
      car.rotation.y = Math.atan2(forward.x, forward.z);

      if (reduced.matches) {
        const distance = 118 / Math.min(1, camera.aspect);
        camera.position.set(0, distance, distance * .38);
        camera.lookAt(0, 0, 0);
      } else {
        camera.position.copy(car.position).addScaledVector(forward, -10);
        camera.position.y = 6.6;
        const target = car.position.clone().addScaledVector(forward, 7);
        target.y = .8;
        camera.lookAt(target);
      }

      el("time").textContent = format(run.lapStart === null ? 0 : now - run.lapStart);
      el("best").textContent = best === null ? "None yet" : format(best);
      el("laps").textContent = String(run.laps);
      el("speed").textContent = `${Math.round(run.speed * 3.6)} km/h`;
    }

    function resize() {
      const { clientWidth: w, clientHeight: h } = view;
      if (!w || !h) return;
      renderer.setSize(w, h, false);
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
    }
    new ResizeObserver(resize).observe(view);
    resize();

    let previousFrame = performance.now();
    renderer.setAnimationLoop(now => {
      const dt = clamp((now - previousFrame) / 1000, 0, .05);
      previousFrame = now;
      update(now, dt);
      renderer.render(scene, camera);
    });
  }
</script>
</body>
</html>
