    #error { top: 50%; left: 50%; width: min(90%, 420px); transform: translate(-50%, -50%); }
  </style>
</head>
<body>
  <section id="hud" aria-label="Race statistics">
    <h1>Apex Loop</h1>
    <dl>
      <dt>Lap</dt><dd id="lap">1</dd>
      <dt>Time</dt><dd id="time">0:00.000</dd>
      <dt>Best</dt><dd id="best">--:--.---</dd>
      <dt>Speed</dt><dd id="speed">0 km/h</dd>
    </dl>
  </section>
  <div id="controls">W ↑ Accelerate · S ↓ Brake · A D / ← → Steer · R Restart</div>
  <p id="error" role="alert" hidden></p>

  <script type="module">
    try {
      const THREE = await import(
        "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js"
      );
      start(THREE);
    } catch (error) {
      const panel = document.getElementById("error");
      panel.textContent = "Could not start Apex Loop. Check your internet connection and browser WebGL support.";
      panel.hidden = false;
      console.error(error);
    }

    function start(T) {
      const scene = new T.Scene();
      scene.background = new T.Color(0xffd4a2);
      scene.fog = new T.Fog(0xffd4a2, 100, 260);

      const camera = new T.PerspectiveCamera(60, 1, 0.1, 300);
      const renderer = new T.WebGLRenderer({ antialias: true });
      renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
      renderer.domElement.setAttribute("aria-label", "Apex Loop race view");
      document.body.prepend(renderer.domElement);

      scene.add(new T.HemisphereLight(0xfff2d8, 0xab694d, 2));
      const sun = new T.DirectionalLight(0xffe4bd, 2);
      sun.position.set(-40, 65, 25);
      scene.add(sun);

      const curve = new T.CatmullRomCurve3(
        [[0, 52], [-43, 45], [-63, 12], [-48, -34], [-12, -48],
         [32, -43], [60, -14], [51, 21], [34, 45]]
          .map(([x, z]) => new T.Vector3(x, 0, z)),
        true
      );
      curve.arcLengthDivisions = 1600;
      const length = curve.getLength();
      const halfRoad = 5.5;
      const storageKey = "apex-loop-v1-best-seconds";
      const keys = new Set();
      const state = {
        distance: 0, offset: 0, speed: 0, lap: 1,
        startedAt: null, best: readBest()
      };
      const hud = Object.fromEntries(
        ["lap", "time", "best", "speed"].map(id => [id, document.getElementById(id)])
      );

      function readBest() {
        try {
          const value = Number(localStorage.getItem(storageKey));
          return Number.isFinite(value) && value > 0 ? value : null;
        } catch {
          return null;
        }
      }

      function sample(distance) {
        const u = ((distance % length) + length) % length / length;
        const point = curve.getPointAt(u);
        const forward = curve.getTangentAt(u);
        const right = new T.Vector3(forward.z, 0, -forward.x);
        return { point, forward, right };
      }

      function material(color) {
        return new T.MeshStandardMaterial({ color, flatShading: true });
      }

      function box(parent, color, w, h, d, x, y, z) {
        const mesh = new T.Mesh(new T.BoxGeometry(w, h, d), material(color));
        mesh.position.set(x, y, z);
        parent.add(mesh);
        return mesh;
      }

      function strip(left, right, y, color) {
        const positions = [];
        const indices = [];
        const count = 320;
        for (let i = 0; i <= count; i++) {
          const frame = sample(length * i / count);
          for (const offset of [left, right]) {
            const p = frame.point.clone().addScaledVector(frame.right, offset);
            positions.push(p.x, y, p.z);
          }
          if (i < count) {
            const a = i * 2;
            indices.push(a, a + 2, a + 1, a + 1, a + 2, a + 3);
          }
        }
        const geometry = new T.BufferGeometry();
        geometry.setAttribute("position", new T.Float32BufferAttribute(positions, 3));
        geometry.setIndex(indices);
        geometry.computeVertexNormals();
        scene.add(new T.Mesh(geometry, material(color)));
      }

      box(scene, 0xd79260, 560, 0.2, 560, 0, -0.12, 0);
      strip(-7.3, 7.3, 0.01, 0xbe694c);
      strip(-halfRoad, halfRoad, 0.02, 0x353848);
      strip(-5.3, -5.1, 0.035, 0xffdfae);
      strip(5.1, 5.3, 0.035, 0xffdfae);

      for (let d = 7; d < length - 4; d += 8) {
        const { point, forward } = sample(d);
        const dash = box(scene, 0xe7be73, 0.13, 0.02, 2.9, point.x, 0.04, point.z);
        dash.rotation.y = Math.atan2(forward.x, forward.z);
      }

      const finish = new T.Group();
      const line = sample(0);
      finish.position.copy(line.point);
      finish.rotation.y = Math.atan2(line.forward.x, line.forward.z);
      scene.add(finish);
      for (let row = 0; row < 2; row++) {
        for (let col = 0; col < 14; col++) {
          box(finish, (row + col) % 2 ? 0xfdf0d8 : 0x202434,
            0.75, 0.02, 0.55, (col - 6.5) * 0.75, 0.045, (row - 0.5) * 0.55);
        }
      }

      for (let i = 0; i < 18; i++) {
        const angle = i * Math.PI * 2 / 18;
        const radius = 93 + (i * 17 % 25);
        const height = 6 + (i * 13 % 15);
        const mesa = new T.Mesh(
          new T.CylinderGeometry(4 + i % 4, 9 + i % 5, height, 5),
          material(i % 2 ? 0xa85346 : 0xc46e4f)
        );
        mesa.position.set(Math.cos(angle) * radius, height / 2 - 0.02,
                          Math.sin(angle) * radius);
        mesa.rotation.y = i * 0.7;
        scene.add(mesa);
      }

      const car = new T.Group();
      scene.add(car);
      box(car, 0x16ccaa, 1.8, 0.45, 3.1, 0, 0.54, 0);
      box(car, 0x163345, 1.38, 0.48, 1.45, 0, 0.98, -0.18);
      box(car, 0x16ccaa, 1.2, 0.12, 1.25, 0, 1.23, -0.2);
      box(car, 0xff664f, 1.45, 0.13, 0.06, 0, 0.58, -1.56);
      for (const x of [-0.9, 0.9]) {
        for (const z of [-0.97, 0.97]) {
          const tire = new T.Mesh(
            new T.CylinderGeometry(0.32, 0.32, 0.32, 8), material(0x1e2028)
          );
          tire.rotation.z = Math.PI / 2;
          tire.position.set(x, 0.33, z);
          car.add(tire);
        }
      }

      function format(seconds) {
        if (seconds === null) return "--:--.---";
        const ms = Math.max(0, Math.floor(seconds * 1000));
        return `${Math.floor(ms / 60000)}:${String(Math.floor(ms / 1000) % 60).padStart(2, "0")}.${String(ms % 1000).padStart(3, "0")}`;
      }

      function updateRace(dt, now) {
        const throttle = keys.has("KeyW") || keys.has("ArrowUp");
        const brake = keys.has("KeyS") || keys.has("ArrowDown");
        const steer = Number(keys.has("KeyD") || keys.has("ArrowRight")) -
                      Number(keys.has("KeyA") || keys.has("ArrowLeft"));
        const limit = Math.abs(state.offset) > halfRoad - 0.65 ? 16 : 46;
        const acceleration = brake ? -46 : throttle ? 22 : -9;
        state.speed = Math.max(0, state.speed + acceleration * dt);
        state.speed = Math.min(state.speed, Math.max(limit, state.speed - 38 * dt));
        state.offset = T.MathUtils.clamp(
          state.offset + steer * Math.min(state.speed * 0.34, 11) * dt,
          -6.3, 6.3
        );

        if (state.speed > 0 && state.startedAt === null) {
          state.startedAt = now - dt * 1000;
        }
        const travel = state.speed * dt;
        const remaining = length - state.distance;
        state.distance += travel;
        if (state.distance >= length) {
          const crossing = now - (1 - remaining / travel) * dt * 1000;
          const lapTime = (crossing - state.startedAt) / 1000;
          if (state.best === null || lapTime < state.best) {
            state.best = lapTime;
            try {
              localStorage.setItem(storageKey, String(lapTime));
            } catch {
              // The session best still works when storage is blocked.
            }
          }
          state.distance -= length;
          state.lap++;
          state.startedAt = crossing;
        }

        hud.lap.textContent = state.lap;
        hud.time.textContent = format(
          state.startedAt === null ? 0 : (now - state.startedAt) / 1000
        );
        hud.best.textContent = format(state.best);
        hud.speed.textContent = `${Math.round(state.speed * 3.6)} km/h`;
      }

      function draw(dt) {
        const { point, forward, right } = sample(state.distance);
        car.position.copy(point).addScaledVector(right, state.offset);
        car.position.y = 0.025;
        car.rotation.y = Math.atan2(forward.x, forward.z);

        const eye = car.position.clone().addScaledVector(forward, -9);
        eye.y += 5;
        camera.position.lerp(eye, dt === 0 ? 1 : 1 - Math.exp(-8 * dt));
        const target = car.position.clone().addScaledVector(forward, 6);
        target.y += 0.8;
        camera.lookAt(target);
        renderer.render(scene, camera);
      }

      const controls = new Set([
        "KeyW", "KeyA", "KeyS", "KeyD", "ArrowUp", "ArrowLeft",
        "ArrowDown", "ArrowRight", "KeyR"
      ]);
      window.addEventListener("keydown", event => {
        if (!controls.has(event.code)) return;
        event.preventDefault();
        if (event.code === "KeyR") {
          if (!event.repeat) {
            Object.assign(state, {
              distance: 0, offset: 0, speed: 0, lap: 1, startedAt: null
            });
            draw(0);
          }
        } else {
          keys.add(event.code);
        }
      });
      window.addEventListener("keyup", event => keys.delete(event.code));
      window.addEventListener("blur", () => keys.clear());
      document.addEventListener("visibilitychange", () => keys.clear());

      function resize() {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
      }

      window.addEventListener("resize", resize);
      resize();
      draw(0);

      let previous = performance.now();
      renderer.setAnimationLoop(now => {
        const dt = Math.min(Math.max(0, (now - previous) / 1000), 0.05);
        previous = now;
        updateRace(dt, now);
        draw(dt);
      });
    }
  </script>
</body>
</html>
