    import * as T from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

    const TAU = Math.PI * 2;
    const HALF = 6.5;
    const STEPS = 240;
    const storageKey = 'cinder-circuit.best.v1';
    const lapText = document.querySelector('#lap');
    const bestText = document.querySelector('#best');
    const status = document.querySelector('#status');
    const clamp = T.MathUtils.clamp;
    const radius = a => 49 + 7 * Math.cos(2 * a) + 4 * Math.sin(3 * a);
    const point = (a, offset = 0, y = 0) =>
      new T.Vector3(Math.cos(a) * (radius(a) + offset), y,
                    Math.sin(a) * (radius(a) + offset));

    const scene = new T.Scene();
    scene.background = new T.Color(0xa4c9c6);
    scene.fog = new T.Fog(0xa4c9c6, 80, 205);
    const camera = new T.PerspectiveCamera(64, 1, 0.1, 250);
    const renderer = new T.WebGLRenderer({ antialias: true });
    renderer.domElement.setAttribute('aria-label', 'Cinder Circuit race track');
    document.body.append(renderer.domElement);

    scene.add(new T.HemisphereLight(0xfff0dc, 0x51705d, 2.1));
    const sun = new T.DirectionalLight(0xffe1b6, 2.3);
    sun.position.set(-30, 65, 25);
    scene.add(sun);

    const material = color => new T.MeshStandardMaterial({ color, flatShading: true });
    function mesh(parent, geometry, mat, x, y, z) {
      const m = new T.Mesh(geometry, mat);
      m.position.set(x, y, z);
      parent.add(m);
      return m;
    }
    const ground = mesh(scene, new T.PlaneGeometry(500, 500), material(0x537e60),
                        0, -0.05, 0);
    ground.rotation.x = -Math.PI / 2;

    function strip(inner, outer, y, colorAt) {
      const positions = [], colors = [];
      for (let i = 0; i < STEPS; i++) {
        const a = TAU * i / STEPS, b = TAU * (i + 1) / STEPS;
        const p = point(a, inner, y), q = point(a, outer, y);
        const r = point(b, inner, y), s = point(b, outer, y);
        const c = new T.Color(colorAt(i));
        for (const v of [p, r, q, q, r, s]) {
          positions.push(v.x, v.y, v.z);
          colors.push(c.r, c.g, c.b);
        }
      }
      const geometry = new T.BufferGeometry();
      geometry.setAttribute('position', new T.Float32BufferAttribute(positions, 3));
      geometry.setAttribute('color', new T.Float32BufferAttribute(colors, 3));
      geometry.computeVertexNormals();
      scene.add(new T.Mesh(geometry, new T.MeshStandardMaterial({ vertexColors: true })));
    }

    strip(-HALF, HALF, 0, i => i % 2 ? 0x353f46 : 0x374149);
    const curb = i => Math.floor(i / 2) % 2 ? 0xf6e7cd : 0xcf522c;
    strip(-HALF, -HALF + 0.55, 0.02, curb);
    strip(HALF - 0.55, HALF, 0.02, curb);

    const white = material(0xf9edda), dark = material(0x242b2b);
    const orange = material(0xff762e), glass = material(0x245064);
    for (let row = 0; row < 2; row++) {
      for (let col = 0; col < 10; col++) {
        mesh(scene, new T.BoxGeometry(1.3, 0.025, 0.65),
             (row + col) % 2 ? white : dark,
             radius(0) - HALF + (col + 0.5) * 1.3, 0.02, (row - 0.5) * 0.65);
      }
    }

    const trunk = material(0x72533d), leaves = material(0x285a49);
    const trunkGeo = new T.CylinderGeometry(0.22, 0.32, 1.5, 5);
    const leafGeo = new T.ConeGeometry(1.65, 4, 5);
    for (let i = 0; i < 76; i++) {
      const a = TAU * i / 76;
      const p = point(a, (i % 2 ? 1 : -1) * (11 + (i * 13 % 19)));
      mesh(scene, trunkGeo, trunk, p.x, 0.74, p.z);
      const crown = mesh(scene, leafGeo, leaves, p.x, 2.8, p.z);
      crown.rotation.y = i;
      crown.scale.setScalar(0.8 + (i % 5) * 0.13);
    }

    const model = new T.Group();
    scene.add(model);
    mesh(model, new T.BoxGeometry(1.95, 0.48, 3.35), orange, 0, 0.58, 0);
    mesh(model, new T.BoxGeometry(1.47, 0.46, 1.45), glass, 0, 1.03, -0.18);
    mesh(model, new T.BoxGeometry(1.62, 0.16, 0.4), dark, 0, 0.92, -1.42);
    const tire = new T.CylinderGeometry(0.39, 0.39, 0.35, 10);
    for (const x of [-0.98, 0.98]) {
      for (const z of [-1.07, 1.07]) {
        mesh(model, tire, dark, x, 0.39, z).rotation.z = Math.PI / 2;
      }
      mesh(model, new T.BoxGeometry(0.45, 0.17, 0.05), white, x * 0.69, 0.62, 1.69);
    }

    let best = Infinity;
    try {
      const saved = Number(localStorage.getItem(storageKey));
      if (Number.isFinite(saved) && saved > 0) best = saved;
    } catch {}
    function format(seconds) {
      const ms = Math.floor(seconds * 1000);
      const part = (n, width) => String(n).padStart(width, '0');
      return `${Math.floor(ms / 60000)}:${part(Math.floor(ms / 1000) % 60, 2)}.${part(ms % 1000, 3)}`;
    }
    bestText.textContent = Number.isFinite(best) ? format(best) : '--';

    const keys = new Set();
    const drivingKeys = new Set([
      'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight',
      'KeyW', 'KeyA', 'KeyS', 'KeyD', 'Space', 'KeyR'
    ]);
    let resetRequested = false;
    let lastFrame = null;
    window.addEventListener('keydown', e => {
      if (!drivingKeys.has(e.code)) return;
      e.preventDefault();
      keys.add(e.code);
      if (e.code === 'KeyR' && !e.repeat) resetRequested = true;
    });
    window.addEventListener('keyup', e => keys.delete(e.code));
    window.addEventListener('blur', () => keys.clear());
    document.addEventListener('visibilitychange', () => {
      keys.clear();
      lastFrame = null;
    });

    const car = { x: 0, z: 0, heading: 0, speed: 0 };
    const race = { angle: 0, progress: 0, elapsed: 0, running: false };
    const up = () => keys.has('ArrowUp') || keys.has('KeyW');
    const down = () => keys.has('ArrowDown') || keys.has('KeyS');

    function reset() {
      Object.assign(car, { x: radius(0), z: 0, heading: 0, speed: 0 });
      Object.assign(race, { angle: 0, progress: 0, elapsed: 0, running: false });
      status.textContent = 'Press ↑ or W to start';
      resetRequested = false;
    }

    function updateLap(angle, dt) {
      const difference = angle - race.angle;
      const delta = Math.atan2(Math.sin(difference), Math.cos(difference));
      race.angle = angle;
      if (!race.running) return;
      const before = race.progress;
      race.progress += delta;
      race.elapsed += dt;
      if (race.progress < TAU) return;

      // Split the step at the finish so its remainder counts toward the next lap.
      const remainder = dt * (1 - clamp((TAU - before) / delta, 0, 1));
      const completed = race.elapsed - remainder;
      if (completed < best) {
        best = completed;
        bestText.textContent = format(best);
        try { localStorage.setItem(storageKey, String(best)); } catch {}
        status.textContent = `New best · ${format(completed)}`;
      } else {
        status.textContent = `Last lap · ${format(completed)}`;
      }
      race.elapsed = remainder;
      race.progress -= TAU;
    }

    function drive(dt) {
      const throttle = Number(up()) - Number(down());
      const steer = Number(keys.has('KeyD') || keys.has('ArrowRight')) -
                    Number(keys.has('KeyA') || keys.has('ArrowLeft'));
      if (throttle !== 0 && !race.running) {
        race.running = true;
        status.textContent = 'Lap in progress';
      }
      const braking = keys.has('Space');
      car.speed += (braking ? 0 : throttle * 27) * dt;
      car.speed *= Math.exp(-(braking ? 6 : throttle ? 0.45 : 1.25) * dt);
      car.speed = clamp(car.speed, -12, 43);
      car.heading -= steer * Math.sign(car.speed) *
                     Math.min(Math.abs(car.speed) / 7, 1) * 1.85 * dt;

      const dx = Math.sin(car.heading) * car.speed * dt;
      const dz = Math.cos(car.heading) * car.speed * dt;
      const x = car.x + dx, z = car.z + dz;
      const angle = Math.atan2(z, x);
      const length = Math.hypot(x, z);
      const center = radius(angle);
      const allowed = clamp(length, center - HALF + 1.15, center + HALF - 1.15);
      car.x = Math.cos(angle) * allowed;
      car.z = Math.sin(angle) * allowed;
      if (length !== allowed) car.speed *= Math.exp(-3 * dt);
      updateLap(angle, dt);
    }

    const eye = new T.Vector3();
    const look = new T.Vector3();
    function follow(dt, snap) {
      const fx = Math.sin(car.heading), fz = Math.cos(car.heading);
      model.position.set(car.x, 0.025, car.z);
      model.rotation.y = car.heading;
      eye.set(car.x - fx * 9, 5.4, car.z - fz * 9);
      look.set(car.x + fx * 5, 0.75, car.z + fz * 5);
      camera.position.lerp(eye, snap ? 1 : 1 - Math.exp(-7 * dt));
      camera.lookAt(look);
    }

    function resize() {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
      renderer.setSize(innerWidth, innerHeight);
    }
    window.addEventListener('resize', resize);
    resize();
    reset();
    follow(0, true);

    function frame(now) {
      const dt = lastFrame === null ? 0 : (now - lastFrame) / 1000;
      lastFrame = now;
      const snap = resetRequested;
      if (snap) reset();
      if (!snap && dt > 0 && !document.hidden) {
        const simTime = Math.min(dt, 0.1);
        if (race.running) race.elapsed += dt - simTime;
        const steps = Math.ceil(simTime * 120);
        for (let i = 0; i < steps; i++) drive(simTime / steps);
      }
      follow(Math.min(dt, 0.1), snap);
      lapText.textContent = format(race.elapsed);
      renderer.render(scene, camera);
      requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  </script>
</body>
</html>
```

### Run and verify

From the folder containing `index.html`, run `python3 -m http.server 8000`, then open `http://localhost:8000`. The page needs internet access to load the pinned Three.js module.

| Browser check | Expected result from code inspection |
|---|---|
| Load and resize the page. Check the console. | The track, car, and HUD appear. Resizing does not stretch the scene or hide the controls. No console errors. |
| Drive with both WASD and the arrows. Try Space and steer into a curb. | Both key sets work. Space slows the car. The curb keeps it on the road and cuts speed. |
| Follow the track in the direction the car faces at spawn, then cross the checkered line. | The first complete circuit records a best lap. The current timer starts counting the next lap. |
| Complete a slower lap, then a faster one. Reload from the same URL. | Only the faster lap replaces the best. The value survives reload when browser storage is available. |
| Reverse across the line, then drive forward over it repeatedly without going around the track. | No lap is awarded. Reversing subtracts progress instead of creating another finish. |
| Press R mid-lap, then switch browser tabs while holding a drive key. | R returns the car to the line and clears the current lap without erasing the best. Returning to the tab does not leave the throttle stuck or count time spent away. |

**Open decision:** The driving feel is unmeasured. I would tune steering and curb drag only after driving several laps in the browser.

Save this as `index.html`. It contains a single-track Three.js racer with keyboard steering, a chase camera, a lap timer, and a best lap saved in the browser. There is no build step. Three.js loads from a pinned CDN version, so the game needs an internet connection.

**Controls:** Arrow keys or WASD to drive. Brake with Down or S. Press R to restart the current attempt without clearing your best lap.

**Data shape:** A closed curve defines the track. The car state holds distance along the track, sideways offset, and speed. The lap state holds the start timestamp, completed-lap count, and optional best time. `step(dt, now)` updates the race; `draw(dt)` renders it.

| Design | Tradeoff |
|---|---|
| Free steering with checkpoints | Allows spins and reverse, but needs collision and checkpoint rules to validate laps. |
| Track-relative steering, chosen here | Keeps the driving arcade-simple. You steer across the road, the grass slows you down, and a lap requires advancing one full circuit. |

