</style>
</head>
<body>
<header>
  <h1>Switchback Circuit</h1>
  <dl>
    <div><dt>Current lap</dt><dd id="current">0:00.000</dd></div>
    <div><dt>Best lap</dt><dd id="best">None</dd></div>
    <div><dt>Completed</dt><dd id="completed">0</dd></div>
    <div><dt>Speed</dt><dd id="speed">0 km/h</dd></div>
  </dl>
</header>
<main id="view" aria-label="3D race view">
  <p id="boot" role="status">Loading the circuit…</p>
</main>
<footer>
  <button id="restart" type="button" disabled>Restart run</button>
  <span>Arrow keys / WASD to drive · R to restart</span>
  <span id="status" role="status">Press Up or W to start.</span>
</footer>

<script type="module">
const $ = id => document.getElementById(id);

try {
  const T = await import('https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js');
  start(T);
} catch (error) {
  const boot = $('boot');
  if (boot) boot.textContent = 'Could not load the game. Check your connection and WebGL support, then reload.';
  console.error(error);
}

function start(T) {
  const view = $('view');
  const hud = Object.fromEntries(
    ['current', 'best', 'completed', 'speed', 'status'].map(id => [id, $(id)])
  );
  const scene = new T.Scene();
  scene.background = new T.Color(0xaad8e6);
  scene.fog = new T.Fog(0xaad8e6, 85, 210);
  const camera = new T.PerspectiveCamera(58, 1, 0.1, 250);
  const renderer = new T.WebGLRenderer({ antialias: true });
  renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
  renderer.domElement.setAttribute('aria-label', 'Switchback Circuit track and car');

  scene.add(new T.HemisphereLight(0xffffff, 0x637c4c, 2.1));
  const sun = new T.DirectionalLight(0xffe4bb, 2.3);
  sun.position.set(-35, 65, 28);
  scene.add(sun);

  const material = color => new T.MeshStandardMaterial({ color, flatShading: true });
  function mesh(geometry, mat, parent, x, y, z) {
    const object = new T.Mesh(geometry, mat);
    object.position.set(x, y, z);
    parent.add(object);
    return object;
  }
  function box(w, h, d, mat, parent, x, y, z) {
    return mesh(new T.BoxGeometry(w, h, d), mat, parent, x, y, z);
  }
  box(380, 1, 380, material(0x77a65f), scene, 0, -0.53, 0);

  const curve = new T.CatmullRomCurve3(
    [[-40, 28], [-6, 44], [41, 36], [56, 4], [34, -32],
     [4, -20], [-23, -43], [-56, -23], [-59, 8]]
      .map(([x, z]) => new T.Vector3(x, 0, z)),
    true, 'centripetal'
  );
  curve.arcLengthDivisions = 2400;
  const length = curve.getLength();
  const halfRoad = 5.6;
  const samples = 480;

  function pose(distance) {
    const u = T.MathUtils.euclideanModulo(distance, length) / length;
    const point = curve.getPointAt(u);
    const forward = curve.getTangentAt(u).normalize();
    return { point, forward, right: new T.Vector3(-forward.z, 0, forward.x) };
  }

  function ribbon(left, right, y, color) {
    const vertices = [];
    const indices = [];
    for (let i = 0; i <= samples; i++) {
      const p = pose(i * length / samples);
      for (const offset of [left, right]) {
        vertices.push(p.point.x + p.right.x * offset, y,
                      p.point.z + p.right.z * offset);
      }
      if (i < samples) {
        const a = 2 * i;
        indices.push(a, a + 2, a + 1, a + 1, a + 2, a + 3);
      }
    }
    const geometry = new T.BufferGeometry();
    geometry.setAttribute('position', new T.Float32BufferAttribute(vertices, 3));
    geometry.setIndex(indices);
    geometry.computeVertexNormals();
    mesh(geometry, material(color), scene, 0, 0, 0);
  }

  ribbon(-halfRoad - .55, halfRoad + .55, .01, 0xcb9060);
  ribbon(-halfRoad, halfRoad, .035, 0x373f4b);
  ribbon(-halfRoad + .18, -halfRoad + .34, .045, 0xfff0ce);
  ribbon(halfRoad - .34, halfRoad - .18, .045, 0xfff0ce);

  const white = material(0xfff0ce);
  const black = material(0x202834);
  const orange = material(0xff8739);
  const startLine = new T.Group();
  scene.add(startLine);
  const startPose = pose(0);
  startLine.position.copy(startPose.point);
  startLine.rotation.y = Math.atan2(startPose.forward.x, startPose.forward.z);
  const tile = 2 * halfRoad / 12;
  for (let row = 0; row < 2; row++) {
    for (let col = 0; col < 12; col++) {
      box(tile, .018, .5, (row + col) % 2 ? white : black, startLine,
          (col - 5.5) * tile, .051, (row - .5) * .5);
    }
  }

  const bark = material(0x75472f);
  const foliage = [material(0x2c714b), material(0x498455), material(0x356e65)];
  const trunk = new T.CylinderGeometry(.2, .3, 1.7, 5);
  const crown = new T.ConeGeometry(1.55, 3.7, 6);
  for (let i = 0; i < 49; i++) {
    const p = pose(i * length / 49);
    const side = i % 2 ? 1 : -1;
    const marker = p.point.clone().addScaledVector(p.right, side * 7.3);
    box(.3, .75, .3, i % 3 ? white : orange, scene, marker.x, .375, marker.z);
    const tree = p.point.clone().addScaledVector(p.right, side * (13 + i % 5));
    mesh(trunk, bark, scene, tree.x, .85, tree.z);
    const top = mesh(crown, foliage[i % 3], scene, tree.x, 2.95, tree.z);
    top.rotation.y = i * 1.7;
    top.scale.setScalar(.85 + (i % 4) * .12);
  }

  const car = new T.Group();
  scene.add(car);
  box(1.85, .56, 3.3, orange, car, 0, .62, 0);
  box(1.37, .48, 1.52, material(0x194359), car, 0, 1.07, -.23);
  box(.25, .025, 2.85, white, car, 0, .909, .08);
  const tire = new T.CylinderGeometry(.36, .36, .33, 10);
  const red = material(0xcf302c);
  for (const x of [-.94, .94]) {
    for (const z of [-1.02, 1.02]) {
      mesh(tire, black, car, x, .39, z).rotation.z = Math.PI / 2;
    }
    box(.36, .17, .08, red, car, x * .7, .66, -1.67);
    box(.36, .17, .08, white, car, x * .7, .66, 1.67);
  }

  const storageKey = 'switchback-circuit.best.v1';
  let best = null;
  try {
    const saved = Number(localStorage.getItem(storageKey));
    if (Number.isFinite(saved) && saved > 0) best = saved;
  } catch {}

  const state = { distance: 0, offset: 0, speed: 0, startedAt: null, laps: 0, best };
  const keys = new Set();
  const driving = new Set([
    'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'KeyW', 'KeyA', 'KeyS', 'KeyD'
  ]);
  const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');
  const held = (...codes) => codes.some(code => keys.has(code));
  const clamp = T.MathUtils.clamp;
  const startPrompt = 'Press Up or W to start.';
  let snapCamera = true;

  function reset() {
    Object.assign(state, { distance: 0, offset: 0, speed: 0, startedAt: null, laps: 0 });
    keys.clear();
    snapCamera = true;
    hud.status.textContent = startPrompt;
  }

  addEventListener('keydown', event => {
    if (event.ctrlKey || event.metaKey || event.altKey) return;
    if (driving.has(event.code)) {
      event.preventDefault();
      keys.add(event.code);
    }
    if (event.code === 'KeyR' && !event.repeat) reset();
  });
  addEventListener('keyup', event => keys.delete(event.code));
  addEventListener('blur', () => keys.clear());
  document.addEventListener('visibilitychange', () => keys.clear());
  $('restart').addEventListener('click', reset);

  function step(dt, now) {
    const throttle = held('ArrowUp', 'KeyW');
    const brake = held('ArrowDown', 'KeyS');
    const steer = Number(held('ArrowRight', 'KeyD')) - Number(held('ArrowLeft', 'KeyA'));

    if (state.startedAt === null) {
      if (!throttle || brake) return;
      state.startedAt = now - dt * 1000;
      hud.status.textContent = 'Lap in progress.';
    }

    const offRoad = Math.abs(state.offset) > halfRoad - .65;
    const acceleration = brake ? -36 : throttle ? 19 : -9;
    state.speed = clamp(state.speed + acceleration * dt, 0, 43);
    if (offRoad && state.speed > 15) state.speed = Math.max(15, state.speed - 39 * dt);
    state.offset = clamp(state.offset + steer * Math.min(9, state.speed * .44) * dt,
                         -halfRoad - 1.1, halfRoad + 1.1);
    const travel = state.speed * dt;
    if (state.distance + travel >= length) {
      const fraction = (length - state.distance) / travel;
      const crossedAt = now - dt * 1000 * (1 - fraction);
      const lap = crossedAt - state.startedAt;
      state.laps++;
      state.startedAt = crossedAt;
      state.distance += travel - length;
      const record = state.best === null || lap < state.best;
      if (record) {
        state.best = lap;
        try { localStorage.setItem(storageKey, String(lap)); } catch {}
      }
      hud.status.textContent = `${record ? 'New best' : 'Lap complete'}: ${format(lap)}`;
    } else {
      state.distance += travel;
    }
  }

  function format(ms) {
    const n = Math.max(0, Math.floor(ms));
    return `${Math.floor(n / 60000)}:${String(Math.floor(n / 1000) % 60).padStart(2, '0')}.${String(n % 1000).padStart(3, '0')}`;
  }

  let previous = performance.now();
  function draw(dt, now) {
    const p = pose(state.distance);
    car.position.copy(p.point).addScaledVector(p.right, state.offset);
    car.rotation.y = Math.atan2(p.forward.x, p.forward.z);

    if (reducedMotion.matches) {
      camera.up.set(0, 0, -1);
      camera.position.set(0, 175, 0);
      camera.lookAt(0, 0, 0);
      snapCamera = true;
    } else {
      camera.up.set(0, 1, 0);
      const desired = car.position.clone().addScaledVector(p.forward, -10);
      desired.y = 6.4;
      camera.position.lerp(desired, snapCamera ? 1 : 1 - Math.exp(-8 * dt));
      camera.lookAt(car.position.clone().addScaledVector(p.forward, 6));
      snapCamera = false;
    }

    hud.current.textContent = format(state.startedAt === null ? 0 : now - state.startedAt);
    hud.best.textContent = state.best === null ? 'None' : format(state.best);
    hud.completed.textContent = state.laps;
    hud.speed.textContent = `${Math.round(state.speed * 3.6)} km/h`;
    renderer.render(scene, camera);
  }

  function resize() {
    const w = Math.max(1, view.clientWidth);
    const h = Math.max(1, view.clientHeight);
    camera.aspect = w / h;
    camera.fov = reducedMotion.matches
      ? Math.max(58, T.MathUtils.radToDeg(2 * Math.atan(75 / (175 * camera.aspect))))
      : 58;
    camera.updateProjectionMatrix();
    renderer.setSize(w, h, false);
  }

  $('boot').replaceWith(renderer.domElement);
  $('restart').disabled = false;
  new ResizeObserver(resize).observe(view);
  reducedMotion.addEventListener('change', resize);
  resize();

  renderer.setAnimationLoop(now => {
    const dt = clamp((now - previous) / 1000, 0, .05);
    previous = now;
    if (!document.hidden) step(dt, now);
    draw(dt, now);
  });
}
</script>
</body>
</html>
```

### How I’d verify it

Open the file in a desktop browser. If the browser blocks the CDN import from a local file, serve its directory with `python3 -m http.server 8000` and open `http://localhost:8000/`. I couldn’t run the game here, so these are checks to perform, not test results.

| Check | Expected result |
|---|---|
| Load with DevTools open | The track, car, and HUD appear without console errors. The current lap is zero and a fresh browser profile shows no best lap. |
| Drive with both key sets | Up/W accelerates, Down/S brakes, and left/right steer across the track. Holding a steering key takes the car onto the shoulder and reduces speed. |
| Finish three laps | The first lap sets the best. A deliberately slower lap leaves it unchanged. A faster lap replaces it. Each crossing increments the count once and restarts the current timer. |
| Brake before the finish | Stopping short does not count a lap. The timer keeps running until you finish or restart. |
| Restart and reload | R and the button reset the run without resetting the best. Reloading preserves the best when browser storage is available. |
| Lose focus while holding throttle | Returning to the game does not leave the throttle stuck. Time away still counts toward the active lap. |
| Resize and change motion settings | At 320 px and 200% zoom, the HUD and controls should remain reachable. Reduced-motion mode switches to a fixed overhead camera. |
| Block the CDN and reload | The loading message changes to an error with a recovery hint. |

The chase camera follows the car with exponential smoothing. Reduced-motion mode fixes the camera overhead; the HUD does not animate. I did not test the camera feel in a browser.

**Throughput checkpoint**

- **Blocking first steps:** Choose the track and lap data shape before writing the driving loop.
- **Independent workstreams:** Track rendering, driving, and the HUD have separate responsibilities. No parallel implementation was available in this chat.
- **Shared mutable state:** The driving loop and restart action own race state. Rendering reads it.
- **Smallest safe decomposition:** One HTML file, because the requested game has one track and no assets or build pipeline.

**Principles applied:** *Model the domain* led to track distance and lateral offset instead of free world coordinates and checkpoint flags. *Prove it works* led to browser checks for actual driving, finish-line timing, reload persistence, and narrow layouts rather than a syntax-only check. No product decisions are left open.

Save this as `index.html` to play **Pine Loop**, a single-track time trial. Use **WASD** or the **arrow keys** to drive and **R** to restart. The timer starts when you accelerate, and the best completed lap is saved in your browser when local storage is available.

The file needs an internet connection to load Three.js. Open it in a modern browser. If your browser blocks the module when opened as a local file, serve it over HTTP, for example with `python -m http.server 8000`, then visit `http://localhost:8000`.

**Data shape and design.** The track maps an angle and lane offset to a 3D position. The driver state holds an unwrapped angle, lane offset, and speed. The lap state holds the current lap time and an optional best time. I chose track-relative steering over free-roaming physics so the car follows the bends while you control its line. A lap requires a full turn of forward progress; steering across the road cannot trigger the finish.

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Pine Loop</title>
  <style>
    * { box-sizing: border-box; }
    body {
      margin: 0;
      background: #172721;
      color: #fff9e9;
      font: 16px/1.4 system-ui, sans-serif;
    }
    canvas { position: fixed; inset: 0; display: block; z-index: 0; }
    .hud {
      position: relative;
      z-index: 1;
      width: min(24rem, calc(100% - 2rem));
      margin: 1rem;
      padding: 1rem;
      border: 1px solid #63716a;
      border-radius: 12px;
      background: #172721;
    }
    h1 { margin: 0; font-size: 1.6rem; }
    dl { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .75rem; }
    dt, .help { color: #c9d7d0; }
    dd {
      margin: .15rem 0 0;
      font: bold clamp(1rem, 5vw, 1.4rem) ui-monospace, monospace;
      overflow-wrap: anywhere;
    }
    p { margin: .5rem 0 0; }
    #status { color: #ffd480; }
  </style>
</head>
<body>
  <main class="hud">
    <h1>Pine Loop</h1>
    <dl>
      <div><dt>Current lap</dt><dd id="current">0:00.000</dd></div>
      <div><dt>Best lap</dt><dd id="best">None yet</dd></div>
    </dl>
    <p id="status" role="status">Loading Three.js…</p>
    <p class="help">W / ↑ accelerate · S / ↓ brake<br>
      A D / ← → steer · R restart</p>
  </main>
  <script type="module">
    const status = document.querySelector("#status");
    try {
      const THREE = await import(
        "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js"
      );
      boot(THREE);
    } catch (error) {
      status.textContent = "Could not start. Check your connection and WebGL support, then reload.";
      console.error(error);
    }

    function boot(T) {
      const TAU = 2 * Math.PI;
      const A = 46, B = 30, HALF = 4.5, SEGMENTS = 192;
      const storageKey = "pine-loop.best.v1";
      const current = document.querySelector("#current");
      const bestDisplay = document.querySelector("#best");
      const scene = new T.Scene();
      scene.background = new T.Color(0xc5e4dc);
      scene.fog = new T.Fog(0xc5e4dc, 65, 175);
      const camera = new T.PerspectiveCamera(58, 1, 0.1, 220);
      const renderer = new T.WebGLRenderer({ antialias: true });
      renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
      renderer.domElement.setAttribute("aria-hidden", "true");
      document.body.append(renderer.domElement);

      scene.add(new T.HemisphereLight(0xfff6d7, 0x657c64, 2.3));
      const sun = new T.DirectionalLight(0xffe3b3, 2.2);
      sun.position.set(-28, 45, 18);
      scene.add(sun);

      function material(color) {
        return new T.MeshStandardMaterial({ color, flatShading: true });
      }

      function box(parent, mat, w, h, d, x, y, z) {
        const mesh = new T.Mesh(new T.BoxGeometry(w, h, d), mat);
        mesh.position.set(x, y, z);
        parent.add(mesh);
        return mesh;
      }

      function point(angle, lane = 0, y = 0) {
        const c = Math.cos(angle), s = Math.sin(angle);
        const scale = Math.hypot(B * c, A * s);
        return new T.Vector3(
          A * c + lane * B * c / scale,
          y,
          B * s + lane * A * s / scale
        );
      }

      function strip(inner, outer, y, colors) {
        const positions = [], shades = [];
        const palette = colors.map(color => new T.Color(color));
        for (let i = 0; i < SEGMENTS; i++) {
          const a = TAU * i / SEGMENTS, b = TAU * (i + 1) / SEGMENTS;
          const p = point(a, inner, y), q = point(a, outer, y);
          const r = point(b, inner, y), s = point(b, outer, y);
          const color = palette[Math.floor(i / 3) % palette.length];
          for (const v of [p, r, q, q, r, s]) {
            positions.push(v.x, v.y, v.z);
            shades.push(color.r, color.g, color.b);
          }
        }
        const geometry = new T.BufferGeometry();
        geometry.setAttribute("position", new T.Float32BufferAttribute(positions, 3));
        geometry.setAttribute("color", new T.Float32BufferAttribute(shades, 3));
        geometry.computeVertexNormals();
        scene.add(new T.Mesh(geometry, new T.MeshStandardMaterial({
          vertexColors: true, side: T.DoubleSide
        })));
      }

      box(scene, material(0x63976b), 360, 0.4, 360, 0, -0.24, 0);
      strip(-HALF, HALF, 0, [0x37434a]);
      strip(-HALF - 0.45, -HALF, 0.012, [0xf5ede0, 0xc34c37]);
      strip(HALF, HALF + 0.45, 0.012, [0xf5ede0, 0xc34c37]);

      const cream = material(0xfff5df), dark = material(0x192228);
      for (let row = 0; row < 2; row++) {
        for (let col = 0; col < 12; col++) {
          box(scene, (row + col) % 2 ? dark : cream, 0.75, 0.025, 0.52,
            A - HALF + (col + 0.5) * 0.75, 0.015, (row - 0.5) * 0.52);
        }
      }

      const bark = material(0x79503b);
      const pineMats = [material(0x235b49), material(0x367751), material(0x487e57)];
      const cone = new T.ConeGeometry(1, 2, 5);
      const trunk = new T.CylinderGeometry(0.15, 0.22, 1.3, 5);
      let seed = 1123;
      function random() {
        seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
        return seed / 4294967296;
      }
      for (let i = 0; i < 100; i++) {
        const inner = i < 32;
        const angle = TAU * random();
        const offset = inner ? -8 - 8 * random() : 8 + 30 * random();
        const tree = new T.Group();
        tree.position.copy(point(angle, offset, -0.04));
        tree.rotation.y = TAU * random();
        tree.scale.setScalar(0.7 + random() * 0.85);
        const stem = new T.Mesh(trunk, bark);
        stem.position.y = 0.65;
        tree.add(stem);
        for (let level = 0; level < 3; level++) {
          const crown = new T.Mesh(cone, pineMats[i % 3]);
          crown.scale.setScalar(1.3 - level * 0.23);
          crown.position.y = 1.65 + level * 0.79;
          tree.add(crown);
        }
        scene.add(tree);
      }

      const car = new T.Group();
      const orange = material(0xf06132);
      box(car, orange, 1.55, 0.52, 2.85, 0, 0.53, 0);
      box(car, dark, 1.22, 0.45, 1.27, 0, 0.98, -0.18);
      box(car, orange, 1.05, 0.12, 0.9, 0, 1.24, -0.22);
      for (const side of [-1, 1]) {
        for (const end of [-1, 1]) {
          box(car, dark, 0.36, 0.54, 0.61, side * 0.76, 0.30, end * 0.86);
        }
        box(car, cream, 0.32, 0.16, 0.06, side * 0.48, 0.56, 1.44);
      }
      scene.add(car);

      const driver = { angle: 0, lane: 0, speed: 0 };
      const lap = { phase: "ready", elapsed: 0, finish: TAU, best: null };
      try {
        const saved = Number(localStorage.getItem(storageKey));
        if (Number.isFinite(saved) && saved > 0) lap.best = saved;
      } catch {}

      function format(seconds) {
        const ms = Math.floor(seconds * 1000);
        return `${Math.floor(ms / 60000)}:${String(Math.floor(ms / 1000) % 60)
          .padStart(2, "0")}.${String(ms % 1000).padStart(3, "0")}`;
      }

      function showBest() {
        bestDisplay.textContent = lap.best === null ? "None yet" : format(lap.best);
      }

      const keys = new Set();
      const controls = new Set([
        "KeyW", "KeyA", "KeyS", "KeyD", "KeyR",
        "ArrowUp", "ArrowLeft", "ArrowDown", "ArrowRight"
      ]);
      const down = (a, b) => keys.has(a) || keys.has(b);
      const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)");
      let previous = performance.now(), accumulator = 0;
      const step = 1 / 120;

      function reset() {
        Object.assign(driver, { angle: 0, lane: 0, speed: 0 });
        Object.assign(lap, { phase: "ready", elapsed: 0, finish: TAU });
        accumulator = 0;
        status.textContent = "Accelerate to start the clock.";
        current.textContent = format(0);
        place(0, true);
      }

      addEventListener("keydown", event => {
        if (!controls.has(event.code) || event.ctrlKey || event.metaKey || event.altKey) return;
        event.preventDefault();
        if (event.code === "KeyR") {
          if (!event.repeat) reset();
        } else {
          keys.add(event.code);
        }
      });
      addEventListener("keyup", event => keys.delete(event.code));
      addEventListener("blur", () => keys.clear());
      document.addEventListener("visibilitychange", () => {
        keys.clear();
        previous = performance.now();
        accumulator = 0;
      });

      function advance(dt) {
        const gas = down("KeyW", "ArrowUp");
        const brake = down("KeyS", "ArrowDown");
        if (lap.phase === "ready") {
          if (!gas || brake) return;
          lap.phase = "running";
          status.textContent = "Clock running";
        }

        const steer = Number(down("KeyD", "ArrowRight")) -
          Number(down("KeyA", "ArrowLeft"));
        const onShoulder = Math.abs(driver.lane) > HALF - 0.65;
        const limit = onShoulder ? 14 : 33;
        const acceleration = brake ? -31 : gas && driver.speed < limit ? 15 : -7;
        driver.speed = T.MathUtils.clamp(driver.speed + acceleration * dt, 0,
          Math.max(limit, driver.speed - 12 * dt));
        driver.lane = T.MathUtils.clamp(
          driver.lane + steer * Math.min(7, driver.speed * 0.32) * dt,
          -HALF - 0.2, HALF + 0.2
        );

        const old = driver.angle;
        const metric = point(old + 0.001, driver.lane)
          .distanceTo(point(old, driver.lane)) / 0.001;
        driver.angle += driver.speed * dt / metric;
        if (driver.angle >= lap.finish) {
          const fraction = (lap.finish - old) / (driver.angle - old);
          const time = lap.elapsed + dt * fraction;
          if (lap.best === null || time < lap.best) {
            lap.best = time;
            showBest();
            try { localStorage.setItem(storageKey, String(time)); } catch {}
            status.textContent = `New best ${format(time)}`;
          } else {
            status.textContent = `Last lap ${format(time)}`;
          }
          lap.elapsed = dt * (1 - fraction);
          lap.finish += TAU;
        } else {
          lap.elapsed += dt;
        }
      }

      function place(dt, snap = false) {
        car.position.copy(point(driver.angle, driver.lane));
        const forward = point(driver.angle + 0.01, driver.lane)
          .sub(car.position).normalize();
        car.rotation.y = Math.atan2(forward.x, forward.z);

        if (reducedMotion.matches) {
          camera.position.set(0, 112, 0);
          camera.up.set(0, 0, -1);
          camera.lookAt(0, 0, 0);
        } else {
          camera.up.set(0, 1, 0);
          const eye = car.position.clone().addScaledVector(forward, -8);
          eye.y += 5;
          camera.position.lerp(eye, snap ? 1 : 1 - Math.exp(-9 * dt));
          const target = car.position.clone().addScaledVector(forward, 6);
          target.y += 0.65;
          camera.lookAt(target);
        }
      }

      function resize() {
        const w = window.innerWidth, h = window.innerHeight;
        renderer.setSize(w, h);
        camera.aspect = w / h;
        camera.fov = reducedMotion.matches
          ? T.MathUtils.radToDeg(2 * Math.atan(Math.max(0.58, 62 / (112 * camera.aspect))))
          : 58;
        camera.updateProjectionMatrix();
      }

      function frame(now) {
        const dt = Math.max(0, (now - previous) / 1000);
        previous = now;
        if (!document.hidden) {
          accumulator += Math.min(dt, 0.1);
          while (accumulator >= step) {
            advance(step);
            accumulator -= step;
          }
          place(Math.min(dt, 0.1));
          current.textContent = format(lap.elapsed);
          renderer.render(scene, camera);
        }
        requestAnimationFrame(frame);
      }

      addEventListener("resize", resize);
      reducedMotion.addEventListener("change", () => {
        resize();
        place(0, true);
      });
      resize();
      showBest();
      reset();
      requestAnimationFrame(frame);
    }
  </script>
</body>
</html>
