```tsx
'use client';

import { useState } from 'react';

type CellValue = string | number | boolean | null | undefined;

export type ExportColumn<Row> = {
  header: string;
  value: (row: Row) => CellValue;
};

type Format = 'csv' | 'xlsx' | 'pdf';

function download(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function csvCell(value: CellValue) {
  let text = String(value ?? '');

  // Prevent spreadsheet apps from interpreting untrusted strings as formulas.
  // Keep actual numbers, including negative numbers, unchanged.
  if (
    typeof value === 'string' &&
    (/^\s*[=+@-]/.test(text) || /^[\t\r\n]/.test(text))
  ) {
    text = `'${text}`;
  }

  return `"${text.replace(/"/g, '""')}"`;
}

export function ReportExport<Row>({
  rows,
  columns,
  filename = 'report',
  title = 'Report',
}: {
  rows: readonly Row[];
  columns: readonly ExportColumn<Row>[];
  filename?: string;
  title?: string;
}) {
  const [busy, setBusy] = useState<Format | null>(null);
  const [error, setError] = useState('');

  async function exportReport(format: Format) {
    setBusy(format);
    setError('');

    try {
      const headers = columns.map((column) => column.header);
      const values = rows.map((row) =>
        columns.map((column) => column.value(row) ?? null),
      );

      if (format === 'csv') {
        const csv = [headers, ...values]
          .map((row) => row.map(csvCell).join(','))
          .join('\r\n');

        // The BOM helps Excel recognize UTF-8 when opening a CSV directly.
        download(
          new Blob(['\uFEFF', csv], { type: 'text/csv;charset=utf-8' }),
          `${filename}.csv`,
        );
      } else if (format === 'xlsx') {
        const { default: ExcelJS } = await import('exceljs');
        const workbook = new ExcelJS.Workbook();
        const sheet = workbook.addWorksheet('Report', {
          views: [{ state: 'frozen', ySplit: 1 }],
        });

        sheet.addRow(headers).font = { bold: true };
        sheet.addRows(values);
        headers.forEach((header, index) => {
          sheet.getColumn(index + 1).width = Math.min(
            40,
            Math.max(14, header.length + 2),
          );
        });

        const buffer = await workbook.xlsx.writeBuffer();
        download(
          new Blob([new Uint8Array(buffer)], {
            type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
          }),
          `${filename}.xlsx`,
        );
      } else {
        const [{ jsPDF }, { autoTable }] = await Promise.all([
          import('jspdf'),
          import('jspdf-autotable'),
        ]);
        const doc = new jsPDF({ orientation: 'landscape' });

        doc.setFontSize(16);
        doc.text(title, 14, 16);

        autoTable(doc, {
          startY: 22,
          head: [headers],
          body: values.map((row) => row.map((value) => String(value ?? ''))),
          styles: { fontSize: 8, overflow: 'linebreak' },
          showHead: 'everyPage',
        });

        doc.save(`${filename}.pdf`);
      }
    } catch (err) {
      console.error(`Report ${format} export failed`, err);
      setError(`Could not export ${format.toUpperCase()}. Please try again.`);
    } finally {
      setBusy(null);
    }
  }

  return (
    <div role="group" aria-label="Export report">
      {(['csv', 'xlsx', 'pdf'] as const).map((format) => (
        <button
          key={format}
          type="button"
          disabled={busy !== null || rows.length === 0 || columns.length === 0}
          onClick={() => void exportReport(format)}
        >
          {busy === format ? 'Exporting…' : `Download ${format.toUpperCase()}`}
        </button>
      ))}
      {error && <p role="alert">{error}</p>}
    </div>
  );
}
