```tsx
// components/ReportExport.tsx
'use client';

import { useState } from 'react';

type CellValue = string | number | boolean | Date | null | undefined;
type Format = 'csv' | 'xlsx' | 'pdf';

export type ExportColumn<Row> = {
  header: string;
  value: (row: Row) => CellValue;
};

function normalize(value: CellValue): string | number | boolean {
  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? '' : value.toISOString();
  }
  return value ?? '';
}

function csvField(value: string | number | boolean): string {
  let text = String(value);

  // Prevent text from being interpreted as a formula by spreadsheet apps.
  // Actual numbers, including negative numbers, are left alone.
  if (
    typeof value === 'string' &&
    /^(?:[\t\r\n]|\s*[=+\-@])/.test(text)
  ) {
    text = `'${text}`;
  }

  return `"${text.replace(/"/g, '""')}"`;
}

function download(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 30_000);
}

export default function ReportExport<Row>({
  rows,
  columns,
  filename = 'report',
  title = 'Report',
}: {
  rows: readonly Row[];
  columns: readonly ExportColumn<Row>[];
  filename?: string;
  title?: string;
}) {
  const [busy, setBusy] = useState<Format | null>(null);
  const [error, setError] = useState('');

  async function exportReport(format: Format) {
    setBusy(format);
    setError('');

    try {
      const headers = columns.map(({ header }) => header);
      const body = rows.map((row) =>
        columns.map(({ value }) => normalize(value(row))),
      );

      switch (format) {
        case 'csv': {
          const csv = [headers, ...body]
            .map((row) => row.map(csvField).join(','))
            .join('\r\n');

          // The BOM helps Excel recognize the file as UTF-8.
          download(
            new Blob(['\uFEFF', csv], { type: 'text/csv;charset=utf-8' }),
            `${filename}.csv`,
          );
          break;
        }

        case 'xlsx': {
          const { Workbook } = await import('exceljs');
          const workbook = new Workbook();
          const sheet = workbook.addWorksheet('Report');

          sheet.addRow(headers).font = { bold: true };
          sheet.views = [{ state: 'frozen', ySplit: 1 }];
          sheet.addRows(body);

          headers.forEach((header, i) => {
            sheet.getColumn(i + 1).width = Math.min(
              40,
              Math.max(14, header.length + 4),
            );
          });

          const buffer = await workbook.xlsx.writeBuffer();
          download(
            new Blob([new Uint8Array(buffer)], {
              type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            }),
            `${filename}.xlsx`,
          );
          break;
        }

        case 'pdf': {
          const [{ jsPDF }, { autoTable }] = await Promise.all([
            import('jspdf'),
            import('jspdf-autotable'),
          ]);

          const doc = new jsPDF({ orientation: 'landscape' });
          doc.setFontSize(16);
          doc.text(title, 14, 16);

          autoTable(doc, {
            startY: 23,
            head: [headers],
            body: body.map((row) => row.map(String)),
            showHead: 'everyPage',
            horizontalPageBreak: true,
            styles: { fontSize: 9, overflow: 'linebreak' },
          });

          doc.save(`${filename}.pdf`);
          break;
        }
      }
    } catch (err) {
      console.error('Report export failed', err);
      setError(`Could not export ${format.toUpperCase()}. Please try again.`);
    } finally {
      setBusy(null);
    }
  }

  return (
    <div role="group" aria-label="Export report">
      {(['csv', 'xlsx', 'pdf'] as const).map((format) => (
        <button
          key={format}
          type="button"
          disabled={busy !== null || columns.length === 0}
          onClick={() => void exportReport(format)}
        >
          {busy === format
            ? `Exporting ${format.toUpperCase()}…`
            : `Export ${format.toUpperCase()}`}
        </button>
      ))}
      {error && <p role="alert">{error}</p>}
    </div>
  );
}
