Pass the filtered, sorted rows **before pagination** to export all matching results, or pass the current page’s rows to export only that page. If your reports contain characters outside jsPDF’s built-in font coverage, embed a font that supports them and set it on both the document and the table.

```tsx
// ReportExport.tsx
'use client';

type Props<Row> = {
  rows: readonly Row[];
  columns: readonly { label: string; value: (row: Row) => unknown }[];
};

export default function ReportExport<Row>({ rows, columns }: Props<Row>) {
  function exportReport(format: 'csv' | 'xlsx' | 'pdf') {
    return async () => {
      try {
        const data = [
          columns.map(({ label }) => label),
          ...rows.map((row) =>
            columns.map(({ value }) => {
              const cell = value(row);
              return typeof cell === 'number' || typeof cell === 'boolean'
                ? cell
                : String(cell ?? '');
            }),
          ),
        ];

        if (format === 'pdf') {
          // Use the browser's print dialog rather than adding a PDF dependency.
          const printWindow = window.open('', '_blank');
          if (!printWindow) throw new Error('Allow pop-ups to print this report.');

          const doc = printWindow.document;
          doc.title = 'Report';
          const style = doc.createElement('style');
          style.textContent = `
            body { font: 12px system-ui, sans-serif; }
            table { width: 100%; border-collapse: collapse; table-layout: fixed; }
            th, td { border: 1px solid #aaa; padding: 5px; text-align: left;
                     vertical-align: top; overflow-wrap: anywhere; }
            thead { display: table-header-group; }
            tr { break-inside: avoid; }
          `;
          doc.head.append(style);

          const table = doc.createElement('table');
          const head = table.createTHead();
          const body = table.createTBody();
          data.forEach((values, index) => {
            const row = (index === 0 ? head : body).insertRow();
            values.forEach((value) => {
              const cell = doc.createElement(index === 0 ? 'th' : 'td');
              cell.textContent = String(value);
              row.append(cell);
            });
          });
          doc.body.append(table);
          printWindow.addEventListener('afterprint', () => printWindow.close(), {
            once: true,
          });
          printWindow.focus();
          printWindow.print();
          return;
        }

        let blob: Blob;
        if (format === 'csv') {
          const csv = data.map((row) =>
            row.map((value) => {
              // Prevent spreadsheet apps from interpreting text as formulas.
              const text =
                typeof value === 'string' && /^[\s\uFEFF]*[=+\-@]|^[\t\r\n]/u.test(value)
                  ? `'${value}`
                  : String(value);
              return `"${text.replace(/"/g, '""')}"`;
            }).join(','),
          ).join('\r\n');
          blob = new Blob(['\uFEFF', csv], { type: 'text/csv;charset=utf-8' });
        } else {
          const { Workbook } = await import('exceljs');
          const workbook = new Workbook();
          workbook.addWorksheet('Report').addRows(data);
          const buffer = await workbook.xlsx.writeBuffer();
          blob = new Blob([buffer], {
            type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
          });
        }

        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `report.${format}`;
        document.body.append(link);
        link.click();
        link.remove();
        window.setTimeout(() => URL.revokeObjectURL(url), 30_000);
      } catch (error) {
        window.alert(error instanceof Error ? error.message : 'Export failed.');
      }
    };
  }

  return (
    <div>
      <button type="button" onClick={exportReport('csv')}>Download CSV</button>
      <button type="button" onClick={exportReport('xlsx')}>Download XLSX</button>
      <button type="button" onClick={exportReport('pdf')}>Save as PDF</button>
    </div>
  );
}
