  link.href = url;
  link.download = filename;
  document.body.append(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function csvCell(value: string | number | boolean) {
  let text = String(value);
  // Keep spreadsheet apps from treating untrusted text as a formula.
  if (typeof value === 'string' && /^(?:\s*[=+\-@]|[\t\r\n])/.test(text)) {
    text = `'${text}`;
  }
  return `"${text.replace(/"/g, '""')}"`;
}

export function ReportExports<Row>({
  rows,
  columns,
}: {
  rows: readonly Row[];
  columns: readonly Column<Row>[];
}) {
  const [exporting, setExporting] = useState(false);
  const [error, setError] = useState('');

  async function exportFile(format: 'csv' | 'xlsx') {
    setError('');
    setExporting(true);

    try {
      const data = [
        columns.map((column) => column.header),
        ...rows.map((row) => columns.map((column) => column.value(row) ?? '')),
      ];

      if (format === 'csv') {
        const csv = data.map((row) => row.map(csvCell).join(',')).join('\r\n');
        download(new Blob(['\uFEFF', csv], { type: 'text/csv;charset=utf-8' }), 'report.csv');
      } else {
        const { Workbook } = await import('exceljs');
        const workbook = new Workbook();
        const sheet = workbook.addWorksheet('Report');
        sheet.addRows(data);
        sheet.getRow(1).font = { bold: true };

        const buffer = await workbook.xlsx.writeBuffer();
        download(
          new Blob([new Uint8Array(buffer)], {
            type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
          }),
          'report.xlsx',
        );
      }
    } catch {
      setError(`Could not export ${format.toUpperCase()}. Please try again.`);
    } finally {
      setExporting(false);
    }
  }

  function exportPdf() {
    setError('');
    const printWindow = window.open('', '_blank');
    if (!printWindow) {
      setError('Allow pop-ups for this site, then try exporting the PDF again.');
      return;
    }

    printWindow.opener = null;
    const doc = printWindow.document;
    doc.title = 'Report';

    const style = doc.createElement('style');
    style.textContent = `
      body { font: 11pt system-ui, sans-serif; }
      table { width: 100%; border-collapse: collapse; }
      th, td { border: 1px solid #bbb; padding: 5px; text-align: left; overflow-wrap: anywhere; }
      thead { display: table-header-group; }
      tr { break-inside: avoid; }
    `;
    doc.head.append(style);

    const table = doc.createElement('table');
    const header = table.createTHead().insertRow();
    for (const column of columns) {
      const cell = doc.createElement('th');
      cell.scope = 'col';
      cell.textContent = column.header;
      header.append(cell);
    }

    const body = table.createTBody();
    for (const row of rows) {
      const tr = body.insertRow();
      for (const column of columns) {
        tr.insertCell().textContent = String(column.value(row) ?? '');
      }
    }

    doc.body.append(table);
    printWindow.focus();
    printWindow.print();
  }

  return (
    <div role="group" aria-label="Export report">
      <button type="button" disabled={exporting} onClick={() => void exportFile('csv')}>
        Export CSV
      </button>
      <button type="button" disabled={exporting} onClick={() => void exportFile('xlsx')}>
        Export XLSX
      </button>
      <button type="button" onClick={exportPdf}>Export PDF</button>
      {error && <p role="alert">{error}</p>}
    </div>
  );
}
