  window.setTimeout(() => URL.revokeObjectURL(url), 30_000);
}

function ReportExports<Row>({
  rows,
  columns,
}: {
  rows: readonly Row[];
  columns: readonly ReportColumn<Row>[];
}) {
  const headers = columns.map(({ label }) => label);

  async function exportFile(format: "csv" | "xlsx") {
    const data = [
      headers,
      ...rows.map((row) => columns.map(({ value }) => value(row) ?? "")),
    ];

    if (format === "csv") {
      const csv = data
        .map((row) =>
          row
            .map((value) => {
              // Keep user-entered text from becoming spreadsheet formulas.
              const text =
                typeof value === "string" && /^[\s\uFEFF]*[=+\-@]|^[\t\r\n]/u.test(value)
                  ? `'${value}`
                  : String(value);
              return `"${text.replace(/"/g, '""')}"`;
            })
            .join(","),
        )
        .join("\r\n");

      downloadReport(
        new Blob(["\uFEFF", csv, "\r\n"], { type: "text/csv;charset=utf-8" }),
        "reports.csv",
      );
      return;
    }

    const { default: ExcelJS } = await import("exceljs");
    const workbook = new ExcelJS.Workbook();
    workbook.addWorksheet("Reports").addRows(data);
    const buffer = await workbook.xlsx.writeBuffer();

    downloadReport(
      new Blob([new Uint8Array(buffer)], {
        type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      }),
      "reports.xlsx",
    );
  }

  return (
    <div className="report-export-actions">
      <button type="button" onClick={() => void exportFile("csv")}>Export CSV</button>
      <button type="button" onClick={() => void exportFile("xlsx")}>Export XLSX</button>
      <button type="button" onClick={() => window.print()}>Export PDF…</button>
    </div>
  );
}
