```tsx
// ReportsExport.tsx
'use client';

import { useState } from 'react';

type Cell = string | number | boolean | null | undefined;

function csvField(value: Cell) {
  let text = String(value ?? '');
  // Keep formula-like strings from executing when opened in a spreadsheet.
  if (typeof value === 'string' && /^(?:\s*[=+\-@]|[\t\r\n])/.test(text)) {
    text = "'" + text;
  }
  return `"${text.replace(/"/g, '""')}"`;
}

function download(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.append(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}

export function ReportsExport<Row>({
  rows,
  columns,
}: {
  rows: readonly Row[];
  columns: readonly { header: string; value: (row: Row) => Cell }[];
}) {
  const [exporting, setExporting] = useState(false);
  const [error, setError] = useState('');

  function getExportRows() {
    return [
      columns.map(({ header }) => header),
      ...rows.map((row) => columns.map(({ value }) => value(row))),
    ];
  }

  function exportCsv() {
    setError('');
    const csv = getExportRows().map((row) => row.map(csvField).join(',')).join('\r\n');
    download(new Blob(['\uFEFF', csv], { type: 'text/csv;charset=utf-8' }), 'reports.csv');
  }

  async function exportXlsx() {
    setError('');
    setExporting(true);
    try {
      const { Workbook } = await import('exceljs');
      const workbook = new Workbook();
      const sheet = workbook.addWorksheet('Reports');
      sheet.addRows(getExportRows().map((row) => row.map((value) => value ?? null)));
      const buffer = await workbook.xlsx.writeBuffer();
      download(
        new Blob([new Uint8Array(buffer)], {
          type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        }),
        'reports.xlsx',
      );
    } catch {
      setError('Could not export XLSX. Please try again.');
    } finally {
      setExporting(false);
    }
  }

  return (
    <>
      <style>{`
        .reports-print { display: none; }
        @media print {
          .reports-screen { display: none !important; }
          .reports-print { display: block; }
          .reports-print table { width: 100%; border-collapse: collapse; }
          .reports-print thead { display: table-header-group; }
          .reports-print tr { break-inside: avoid; }
          .reports-print th, .reports-print td {
            border: 1px solid #aaa;
            padding: 4px;
            text-align: left;
            overflow-wrap: anywhere;
          }
        }
      `}</style>

      <div className="reports-screen">
        <button type="button" onClick={exportCsv}>Export CSV</button>
        <button type="button" onClick={exportXlsx} disabled={exporting}>
          {exporting ? 'Exporting…' : 'Export XLSX'}
        </button>
        <button type="button" onClick={() => window.print()}>Save as PDF</button>
        {error && <p role="alert">{error}</p>}
      </div>

      <section className="reports-print">
        <h1>Reports</h1>
        <table>
          <thead>
            <tr>
              {columns.map(({ header }, i) => <th key={i} scope="col">{header}</th>)}
            </tr>
          </thead>
          <tbody>
            {rows.map((row, i) => (
              <tr key={i}>
                {columns.map(({ value }, j) => (
                  <td key={j}>{String(value(row) ?? '')}</td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </section>
    </>
  );
}
