```tsx
// ReportExports.tsx
'use client';

type Column<Row> = {
  label: string;
  value: (row: Row) => string | number | boolean | null | undefined;
};

function download(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.append(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function csvCell(value: string | number | boolean) {
  let text = String(value);
  // Keep spreadsheet apps from interpreting untrusted text as a formula.
  if (typeof value === 'string' && /^(?:\s*[=+\-@]|[\t\r\n])/.test(text)) {
    text = "'" + text;
  }
  return `"${text.replace(/"/g, '""')}"`;
}

export function ReportExports<Row>({
  rows,
  columns,
}: {
  rows: readonly Row[];
  columns: readonly Column<Row>[];
}) {
  const exportRows = () => [
    columns.map(({ label }) => label),
    ...rows.map((row) => columns.map(({ value }) => value(row) ?? '')),
  ];

  function exportCsv() {
    const csv = exportRows().map((row) => row.map(csvCell).join(',')).join('\r\n');
    download(new Blob(['\uFEFF', csv], { type: 'text/csv;charset=utf-8' }), 'report.csv');
  }

  async function exportXlsx() {
    try {
      const { Workbook } = await import('exceljs');
      const workbook = new Workbook();
      workbook.addWorksheet('Report').addRows(exportRows());
      const buffer = await workbook.xlsx.writeBuffer();
      download(
        new Blob([new Uint8Array(buffer)], {
          type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        }),
        'report.xlsx',
      );
    } catch {
      window.alert('Could not export the report as XLSX.');
    }
  }

  function exportPdf() {
    const preview = window.open('', '_blank');
    if (!preview) {
      window.alert('Allow pop-ups to open the PDF print dialog.');
      return;
    }

    const doc = preview.document;
    doc.title = 'Report';

    const style = doc.createElement('style');
    style.textContent = `
      @page { margin: 12mm; }
      body { font: 11pt system-ui, sans-serif; }
      table { width: 100%; border-collapse: collapse; }
      thead { display: table-header-group; }
      tr { break-inside: avoid; }
      th, td { border: 1px solid #aaa; padding: 5px; text-align: left; overflow-wrap: anywhere; }
    `;
    doc.head.append(style);

    const table = doc.createElement('table');
    const [header, ...body] = exportRows();
    const heading = table.createTHead().insertRow();
    for (const label of header) {
      const th = doc.createElement('th');
      th.scope = 'col';
      th.textContent = label;
      heading.append(th);
    }

    const tbody = table.createTBody();
    for (const values of body) {
      const row = tbody.insertRow();
      for (const value of values) row.insertCell().textContent = String(value);
    }

    doc.body.append(table);
    preview.focus();
    preview.print();
  }

  return (
    <div role="group" aria-label="Export report">
      <button type="button" onClick={exportCsv}>Export CSV</button>
      <button type="button" onClick={exportXlsx}>Export XLSX</button>
      <button type="button" onClick={exportPdf}>Save as PDF…</button>
    </div>
  );
}
